function drawMinimap(){const c=$('minimap'),ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);let px=x=>w/2+x*2.75,pz=z=>h/2+z*2.55;ctx.strokeStyle='#e1d6bc';ctx.lineWidth=12;for(let x of [-34,0,34]){ctx.beginPath();ctx.moveTo(px(x),pz(-44));ctx.lineTo(px(x),pz(45));ctx.stroke();}for(let z of [-32,0,32]){ctx.beginPath();ctx.moveTo(px(-46),pz(z));ctx.lineTo(px(46),pz(z));ctx.stroke();}ZONES.forEach((z,i)=>{ctx.fillStyle='#'+z.color.toString(16).padStart(6,'0');ctx.fillRect(px(z.x)-24,pz(z.z)-22,48,44);ctx.fillStyle='#4b705d';ctx.font='bold 16px sans-serif';ctx.textAlign='center';ctx.fillText(String(i+1),px(z.x),pz(z.z)+5);});ctx.fillStyle='#8ab298';ctx.fillRect(px(0)-28,pz(0)-26,56,52);ctx.fillStyle='#fff9df';ctx.font='22px sans-serif';ctx.fillText('⌂',px(0),pz(0)+8);for(let n of NEIGHBORS){ctx.fillStyle='#bc954c';ctx.beginPath();ctx.arc(px(n.x),pz(n.z),4,0,TAU);ctx.fill();}if(game.waypoint){ctx.strokeStyle='#bc8950';ctx.lineWidth=2;ctx.beginPath();ctx.arc(px(game.waypoint.x),pz(game.waypoint.z),13,0,TAU);ctx.stroke();}ctx.fillStyle='#287d70';ctx.strokeStyle='white';ctx.lineWidth=3;ctx.beginPath();ctx.arc(px(game.player.x),pz(game.player.z),6,0,TAU);ctx.fill();ctx.stroke();}
