function factoryTarget(){if(game.waypoint)return game.waypoint;let f=game.factory;if(game.carry>=30)return{x:0,z:6};for(let i=0;i<4;i++){let k=F.LANES[i].kind;if(f.cargo[k]>0)return{x:F.LANES[i].x,z:11};}let cash=f.lanes.findIndex(l=>l.cash>0);if(cash>=0)return{x:F.LANES[cash].x+1.8,z:12};if(game.supplies>8)return{x:3.3,z:6};return game.dirt.reduce((best,d)=>!best||Math.hypot(d.x-game.player.x,d.z-game.player.z)<Math.hypot(best.x-game.player.x,best.z-game.player.z)?d:best,null);}
function renderExpansion(dt){renderCleanFX(dt);document.body.classList.toggle('tycoon-mode',game.variant==='tycoon');document.body.classList.toggle('journey-mode',game.variant==='journey');if(game.variant!=='tycoon'){if(game.variant==='journey'){$('combohud').classList.remove('show');$('compact-vitals').style.display='none';}return;}
 let f=game.factory,p=game.player;for(let v of machineViews)if(v.rotor)v.rotor.rotation.y+=dt*(f.sites[v.d.id].working||v.d.kind==='vacuum'?5:0);
 for(let l of factoryLabels){let dist=Math.hypot(p.x-l.x,p.z-l.z);l.el.style.display=running&&dist<25?'':'none';let vec=new THREE.Vector3(l.x,l.kind==='nexus'?4.2:l.kind==='order'?2.4:l.kind==='machine'?2.8:1,l.z).project(camera);l.el.style.left=((vec.x*.5+.5)*innerWidth)+'px';l.el.style.top=((-vec.y*.5+.5)*innerHeight)+'px';let html='';if(l.kind==='nexus')html='<span>⌂ '+Math.ceil(game.baseHP/game.baseMax*100)+'%</span><i style="width:'+Math.max(0,game.baseHP/game.baseMax*100)+'%"></i>';
 if(l.kind==='refinery')html=iconSVG('raw')+compactNumber(f.rawBuffer)+'<span>→</span>'+iconSVG('material');if(l.kind==='output')html=iconSVG('material')+compactNumber(game.supplies)+'<small>자동 싣기</small>';
 if(l.kind==='build'){let d=F.SITES.find(d=>d.id===l.id),s=f.sites[d.id];html=iconSVG('money')+compactNumber(d.cost-s.paid)+(d.cores?' '+iconSVG('core')+d.cores:'');if(!game.factoryUnlocked(d))html='⚿';}
 if(l.kind==='machine'){let d=F.SITES.find(d=>d.id===l.id),s=f.sites[d.id],r=F.RECIPES[d.kind];html=iconSVG(r.out)+s.output+'<small>'+(s.working?Math.floor(s.clock/r.time*100)+'%':s.output>=50?'Ⅱ':r.in.material?'▣ '+s.input.material:'♧')+'</small>';}
 if(l.kind==='order'){let q=f.customers.find(c=>c.lane===l.id&&c.phase==='wait');html=q?iconSVG(q.kind)+(q.quantity-q.filled)+'<i style="width:'+(q.patience/q.maxPatience*100)+'%;background:'+(q.patience<25?'#d87a68':'#7bb697')+'"></i>':'';}
 if(l.kind==='stock')html=iconSVG(F.LANES[l.id].kind)+compactNumber(f.lanes[l.id].stock)+'<small>↓</small>';if(l.kind==='till')html=f.lanes[l.id].cash?iconSVG('money')+compactNumber(f.lanes[l.id].cash):'';if(l.el.innerHTML!==html)l.el.innerHTML=html;if(!html)l.el.style.display='none';}
 let customers=f.customers.slice(0,40);for(let i=0;i<customers.length;i++){let c=customers[i];for(let {m,def}of customerParts){dummy.position.set(c.x+def[2],def[3]+Math.abs(Math.sin(visTime*10+i))*.035,c.z+def[4]);dummy.scale.set(def[5],def[6],def[7]);dummy.rotation.set(0,c.phase==='leave'?0:Math.PI,0);dummy.updateMatrix();m.setMatrixAt(i,dummy.matrix);}}for(let {m}of customerParts){m.count=customers.length;m.instanceMatrix.needsUpdate=true;}
 const piles=[];piles.push({kind:'raw',n:f.rawBuffer,x:-2.3,z:5.7});for(let i=0;i<4;i++){let l=f.lanes[i],d=F.LANES[i];piles.push({kind:'money',n:l.cash,x:d.x+1.8,z:d.z});piles.push({kind:d.kind,n:l.stock,x:d.x-.9,z:d.z-1.6});}for(let d of F.SITES){let s=f.sites[d.id],r=F.RECIPES[d.kind];if(s.built&&r)piles.push({kind:r.out,n:s.output,x:d.x+2,z:d.z});}
 for(let c of customers)if(c.filled>0)piles.push({kind:c.kind,n:Math.min(3,c.filled),x:c.x-.2,z:c.z+.35,y:1});
 let counts=Object.fromEntries(Object.keys(stockMeshes).map(k=>[k,0]));for(let q of piles){let mesh=stockMeshes[q.kind];if(!mesh)continue;for(let i=0;i<Math.min(72,q.kind==='money'?Math.ceil(q.n/5):q.n);i++){let n=counts[q.kind]++;if(n>=350)break;dummy.position.set(q.x+(i%3)*.34,(q.y||.33)+Math.floor(i/6)*.20,q.z+(Math.floor(i/3)%2)*.34);dummy.scale.set(.31,.18,.28);dummy.rotation.set(0,0,0);dummy.updateMatrix();mesh.setMatrixAt(n,dummy.matrix);}}for(let [k,m]of Object.entries(stockMeshes)){m.count=Math.min(350,counts[k]);m.instanceMatrix.needsUpdate=true;}
 factoryCart.visible=f.sites.rail.built;if(factoryCart.visible){if(f.railRide){factoryCart.position.set(p.x,0,p.z);factoryCart.rotation.y=p.angle;playerMesh.position.y=.65;}else{let pts=game.railPoints(),seg=Math.floor(visTime/3)%pts.length,a=pts[seg],b=pts[(seg+1)%pts.length],t=visTime/3%1;factoryCart.position.set(a[0]+(b[0]-a[0])*t,0,a[1]+(b[1]-a[1])*t);factoryCart.rotation.y=Math.atan2(b[0]-a[0],b[1]-a[1]);}}
 let context=f.railRide?'레일에서 내리기':Math.hypot(p.x-7,p.z-3)<2.2?'⌂ 수리 · 20':f.sites.rail.built&&game.railDistance().distance<2?'레일 탑승':'';$('interactpanel').classList.toggle('visible',!!context&&running);$('interact').textContent=context;$('interact').disabled=false;document.body.classList.toggle('hurt',performance.now()<damageUntil);}
function updateExpansionHUD(){renderQuestGuide();updateCompactHUD();$('money').textContent=compactNumber(game.money);$('carry').textContent=compactNumber(game.carry);$('supplies').textContent=compactNumber(game.variant==='tycoon'?game.factory.cargo.material:game.supplies);for(let k of ['money','carry','supplies'])$(k).dataset.value=k==='supplies'&&game.variant==='tycoon'?game.factory.cargo.material:game[k];$('carry').closest('.stat').querySelector('.symbol').innerHTML=iconSVG('raw');$('supplies').closest('.stat').querySelector('.symbol').innerHTML=iconSVG('material');$('money').closest('.stat').querySelector('.symbol').innerHTML=iconSVG('money');$('ability').disabled=game.cooldown>0||!running;$('abilitytext').textContent=game.cooldown>0?Math.ceil(game.cooldown):'✧';$('compact-vitals').style.display=game.variant==='journey'?'none':'';
 $('chaptermini').textContent=game.variant==='tycoon'?'W '+game.wave:(game.chapter+1)+' / 8';if(game.variant==='tycoon'){let f=game.factory;$('corecount').textContent=compactNumber(f.cores);let right=document.querySelector('.statusgroup').getBoundingClientRect().right,menuLeft=$('quickmenu').getBoundingClientRect().left;$('corehud').style.left=(right+6)+'px';$('corehud').classList.toggle('second-row',right+6+$('corehud').offsetWidth>menuLeft-8);$('raidclock').textContent='⌂ '+Math.ceil(f.nextWave)+'s';$('cargodock').innerHTML=['toy','cloth','crop','meal'].map(k=>'<span title="'+F.GOODS[k].name+'">'+iconSVG(k)+'<b>'+compactNumber(f.cargo[k])+'</b></span>').join('');$('money').closest('.stat').title='운반해 걷은 돈';$('carry').closest('.stat').title='먼지 자루 · 운반 제한 없음';$('supplies').closest('.stat').title='등에 실은 재생 원료';}else{$('chaptermini').textContent=(game.chapter+1)+' / 8 · '+Math.min(3,game.puzzles[game.chapter].step)+'/3';}
}
function handleExpansionEvent(e){if(e.type==='clean'&&game.variant==='tycoon')cleanSuction(e);if(e.type==='factory_build'){buildEnvironment();save();tone(830,.3);}if(e.type==='cash'){floatReward((e.n>=0?'+':'−')+Math.abs(e.n),e.x,e.z,'gold');if(e.n>0)flyCoins(e.x,e.z,e.n);statKick('money');}if(e.type==='crystal'){floatReward('+'+e.n,e.x,e.z,'core');tone(850,.1);}if(e.type==='cargo'){floatReward('+'+e.n,e.x,e.z);stackKick=Math.min(.6,stackKick+.14);}if(e.type==='refine')floatReward('+'+e.n,3.3,6,'material');if(e.type==='shipment'){let m=new THREE.Mesh(geometries.box,mat(colors[e.kind]||colors.material));m.scale.set(.23,.2,.23);effects.add(m);gifts.push({m,x:e.fromX,z:e.fromZ,tx:e.x,tz:e.z,sy:1.2,age:0});}if(e.type==='damage'){floatReward('−'+e.n,e.x,e.z,'damage');damageUntil=performance.now()+350;}if(e.type==='raid'){tone(210,.3,'triangle');}if(e.type==='knockout')toast('넘어졌어요 · 떨어진 자루를 되찾을 수 있어요');if(e.type==='action_complete'){buildActionViews();save();tone(720,.15);toast('✓ '+e.title);}if(e.type==='action_beat'){tone(e.good?740:240,.12);}if(e.type==='action_touch'){save();}if(e.type==='journey_note')showJourneyNote(e);if(e.type==='journey_solved')save();}
function selectSaveSlot(variant){const key=variant==='tycoon'?'game':variant==='legacy'?'legacy':'story';STORAGE=key==='legacy'?'clean-keep-save-v1':'clean-keep-save-v4-'+key;CHECKPOINT=key==='legacy'?'clean-keep-checkpoint-v1':'clean-keep-checkpoint-v4-'+key;}
function slotExists(variant){try{return !!localStorage.getItem('clean-keep-save-v4-'+(variant==='tycoon'?'game':'story'));}catch{return false;}}
function showTitle(){document.body.classList.add('notplaying');showModal('title','<div class="eyebrow">CLEAN & KEEP</div><h2 class="big-title">마음의 집</h2><p>이야기를 따라 마음의 방을 열거나,<br>청소 공방을 키우며 마을을 지켜요.</p><div class="mode-choices"><button id="choose-story"><span>▤</span><b>스토리 모드</b><small>말씀 · 교제 · 맡김<br>여덟 방과 명의 이전</small></button><button id="choose-game"><span>'+iconSVG('toy')+'</span><b>게임 모드</b><small>수집 · 생산 · 판매<br>구역 물류와 넥서스 방어</small></button></div><p class="smallnote">두 모드는 진행과 저장을 따로 보관합니다.</p>'+btn('legacy-load','이전 버전 저장 열기','ghost'));$('choose-story').onclick=()=>showModeStart('journey');$('choose-game').onclick=()=>showModeStart('tycoon');$('legacy-load').onclick=()=>{selectSaveSlot('legacy');continueGame();};}
function showModeStart(variant){selectedMode=variant;const exists=slotExists(variant);showModal('modepick','<button class="close" id="modeback" aria-label="모드 선택으로">×</button><div class="eyebrow">'+(variant==='tycoon'?'GAME MODE':'STORY MODE')+'</div><h2>'+(variant==='tycoon'?'사방으로 자라는 청소 공방':'내 마음, 그리스도의 집')+'</h2><p>'+(variant==='tycoon'?'먼지를 재생 원료로 바꾸고, 줄 서 있는 손님에게 상품을 판매하세요. 돈과 정화 결정으로 기계·레일·새 구역을 건설하고 중앙 넥서스를 지킵니다.':'예수님과 함께 내 마음의 방을 하나씩 열어 보아요.')+'</p>'+(exists?btn('mode-continue','이어서 하기'):'')+btn('mode-start',exists?'새로 시작하기':'시작하기',exists?'secondary':'')+'<p class="smallnote">'+(variant==='tycoon'?'먼지 운반 제한 없음 · 엔딩 없는 운영 · 실제 나무 피해':'로버트 멍어의 「내 마음 그리스도의 집」에서')+'</p>');$('modeback').onclick=showTitle;if(exists)$('mode-continue').onclick=()=>{selectSaveSlot(variant);continueGame();};$('mode-start').onclick=()=>{if(!exists){beginMode(variant);return;}showModal('newconfirm','<h2>새로 시작할까요?</h2><p>현재 진행은 별도 백업으로 남깁니다. 다른 모드의 저장은 바뀌지 않습니다.</p>'+btn('keep-progress','기존 진행 이어하기')+btn('confirm-fresh','백업 후 새로 시작','secondary'));$('keep-progress').onclick=()=>{selectSaveSlot(variant);continueGame();};$('confirm-fresh').onclick=()=>beginMode(variant);};}
function beginMode(variant){selectSaveSlot(variant);try{const old=localStorage.getItem(STORAGE);if(old)localStorage.setItem(STORAGE+'-backup',old);}catch{}game=new Game();saveSessionReady=true;if(variant==='tycoon')game.startFactory();else game.startJourney();checkpoint=null;buildEnvironment();setCheckpoint();document.body.classList.remove('notplaying');if(variant==='tycoon')showFactoryIntro();else showJourneyStory();}
function showFactoryIntro(){showModal('factoryintro','<div class="eyebrow">첫 공방</div><h2>모아서, 바꾸고,<br>필요한 곳에.</h2><div class="resource-flow"><span>'+iconSVG('raw')+'먼지 자루</span><b>→</b><span>'+iconSVG('material')+'재생 원료</span><b>→</b><span>'+iconSVG('money')+'돈</span></div><ol class="factory-how"><li>이동하며 먼지를 청소해 등에 쌓아요.</li><li>보라색 ↓ 하역장에서 먼지를 전부 내려놓아요. 초록 ♻ 재활용기 옆 연두 발판에서 원료를 실어요.</li><li>판매대 앞 발판에 상품을 쌓아 두세요. 손님이 자동으로 가져가고 옆에 돈을 남겨요.</li><li>금색 발판에 0.8초 멈추면 돈을 나눠 내며 건설돼요. 분홍 결정은 몬스터에게 얻어요.</li></ol><p class="smallnote">넥서스 체력이 0이 되면 운영이 멈춥니다. 첫 습격 전 준비하세요.<br>공장 옆에서 레일을 설치하세요. 선로 가까이에서 탑승하기 · 내리기로 순환 카트를 이용해요.</p>'+btn('factory-go','공방 열기'));$('factory-go').onclick=closeModal;}
function showJourneyStory(){const i=game.chapter,t=CleanHouse.JOURNEY_TEXT[i];showModal('story','<div class="eyebrow">STORY '+(i+1)+' / 8 · '+CHAPTERS[i].name+'</div><h2>'+t[0]+'</h2><div class="storytext"><p>'+t[1]+'</p><p>'+t[2]+'</p></div><div class="puzzle-story"><b>이번 방의 행동</b><p>'+CleanHouse.ACTION_STAGES[i].map(d=>d.title).join(' → ')+'</p></div>'+btn('storygo','함께 들어가기'));$('storygo').onclick=closeModal;}
function showJourneyNote(e){showModal('journeynote','<div class="eyebrow">함께 걷는 마음</div><h2>'+e.title+'</h2><p>'+e.text+'</p>'+btn('note-next','마음에 담고 계속하기'));$('note-next').onclick=closeModal;}
function showJourneyComplete(){if(game.chapter===7){showModal('deed','<div class="eyebrow">명의 이전</div><h2>손님이 아닌,<br>이 집의 주인으로.</h2><div class="deed"><h3>명의 이전</h3><p>저의 존재와 소유, 집 전체를<br>예수 그리스도께 맡깁니다.<br>저는 심부름꾼과 친구로 함께하겠습니다.</p><span class="stamp">신뢰로<br>맡깁니다</span></div>'+btn('sign','집문서에 서명하고 맡기기'));$('sign').onclick=()=>{game.signDeed();save();showModal('ending','<div class="eyebrow">STORY COMPLETE</div><h2>그분의 집에서,<br>함께 살아갑니다.</h2><p>완벽한 청소의 보상으로 얻은 평안이 아닙니다. 그분께 맡긴 집에서 심부름꾼과 친구로 함께합니다.</p>'+btn('story-rest','집에 머무르기')+btn('modes','모드 선택으로','secondary'));$('story-rest').onclick=closeModal;$('modes').onclick=()=>{save();showTitle();};};return;}showModal('complete','<div class="eyebrow">'+CHAPTERS[game.chapter].name+'</div><h2>함께 한 방을 열었습니다.</h2><p>'+CleanHouse.JOURNEY_TEXT[game.chapter][2]+'</p>'+btn('next','다음 방으로'));$('next').onclick=()=>{game.next();buildEnvironment();setCheckpoint();showJourneyStory();};}
function showFactoryDefeat(){save();let q=game.recoveryQuote();showModal('defeat','<div class="eyebrow">나무를 다시 돌봐요</div><h2>넥서스가 쓰러졌어요.</h2><p>복구하면 넥서스는 65%, 내 기운은 75%로 돌아옵니다. 돈 '+q.cash+'을 내고 평판 12와 생산 시간 25초를 잃어요. 다음 습격은 30초 뒤예요.'+(q.cores||q.supplies?'<br>돈이 부족해 정화 결정 '+q.cores+'개 · 재생 원료 '+q.supplies+'개도 사용합니다.':'')+'</p>'+btn('factory-recover','손실을 감수하고 복구하기'));$('factory-recover').onclick=()=>{game.recoverFactory();buildEnvironment();save();closeModal();};}
function showQuickMenu(){if(game.variant==='legacy')return showLegacyMenu();if(game.dead||game.ready||modalKind==='title')return;save();if(game.variant==='journey'){let d=game.puzzleDefs[game.chapter],s=game.puzzles[game.chapter];showModal('menu','<button class="close" id="closemenu" aria-label="닫기">×</button><div class="eyebrow">STORY '+(game.chapter+1)+' / 8</div><h2>'+CHAPTERS[game.chapter].name+'</h2><p>'+CleanHouse.JOURNEY_TEXT[game.chapter][2]+'</p><div class="menu-puzzle"><b>'+d.name+' · '+s.step+'/3</b><p>'+game.puzzleHint(game.chapter)+'</p></div><p class="smallnote">함께 머문 시간 '+formatTime(game.time)+' / '+formatTime(game.duration)+'<br>미션 완료 후 바로 다음 방으로 갈 수 있습니다. 원하는 만큼 머물러도 좋습니다.</p>'+(s.solved&&!game.journey.ending?btn('finish-reflection',game.chapter===7?'명의 이전 서명으로':'다음 방으로','secondary'):'')+btn('menu-resume','계속하기')+btn('menu-save','저장 · 설정','secondary')+btn('mode-home','모드 선택','ghost'));if($('finish-reflection'))$('finish-reflection').onclick=()=>{closeModal();game.finishJourneyRoom();processEvents();};}else{let f=game.factory;showModal('menu','<button class="close" id="closemenu" aria-label="닫기">×</button><div class="eyebrow">GAME · WAVE '+game.wave+'</div><h2>마을 청소 공방</h2><div class="menu-progress"><span>주문 '+f.served+'건 · 이탈 '+f.missed+'명</span><span>♡ '+f.reputation+'</span></div><div class="quick-grid"><button id="factory-build-menu">⚒<br>건설 · 강화</button><button id="factory-recipes">▦<br>생산 안내</button><button id="factory-tools">＋<br>청소 장비</button><button id="factory-route">↓<br>재활용기 찾기</button><button id="factory-tutorial">?<br>플레이 방법</button><button id="factory-sound">♪<br>소리 '+(soundOn?'켜짐':'꺼짐')+'</button></div><p class="smallnote">창고 원료 '+game.supplies+' · 기계 대기 먼지 '+f.rawBuffer+'<br>기차 물류 '+(f.sites.rail.built?'연결됨':'미설치')+' · 창구 매니저 '+(f.sites.clerk.built?'근무 중':'미고용')+'<br>넘어지면 먼지 25%가 떨어지고 기계가 8초 멈춥니다.</p>'+btn('menu-resume','계속 운영하기')+btn('menu-save','저장 · 설정','secondary')+btn('mode-home','모드 선택','ghost'));$('factory-build-menu').onclick=showFactoryBuildMenu;$('factory-recipes').onclick=showFactoryRecipes;$('factory-tools').onclick=showUpgrades;$('factory-route').onclick=()=>{game.waypoint={x:0,z:6};closeModal();};$('factory-tutorial').onclick=showFactoryIntro;$('factory-sound').onclick=()=>{soundOn=!soundOn;initAudio();showQuickMenu();};}
 $('closemenu').onclick=$('menu-resume').onclick=closeModal;$('menu-save').onclick=showPause;$('mode-home').onclick=()=>{save();showTitle();};installQuestMenu();}
function showFactoryBuildMenu(){let f=game.factory;showModal('buildmenu','<button class="close" id="build-close" aria-label="닫기">×</button><div class="eyebrow">돈 '+game.money+' · 정화 결정 '+f.cores+'</div><h2>설비와 방 확장</h2><div class="factory-build-list">'+F.SITES.filter(d=>game.factoryUnlocked(d)).map(d=>{let s=f.sites[d.id],up=s.built&&(F.RECIPES[d.kind]||d.kind==='vacuum');return '<div><button data-site="'+d.id+'"><b>'+d.name+(s.built?' ✓':'')+'</b><small>'+(s.built?'Lv. '+s.level:'돈 '+(d.cost-s.paid)+' · 결정 '+d.cores)+' → 위치 안내</small></button>'+(up?'<button class="machine-up" data-machine="'+d.id+'">강화<br>'+Math.floor(100*Math.pow(1.6,s.level-1))+' / ◆'+(s.level*3)+'</button>':'')+'</div>';}).join('')+'</div><p class="smallnote">건설 발판 위에 서면 돈이 조금씩 투입됩니다. 필요한 결정은 완공할 때 소비합니다. 투입한 돈은 저장됩니다.</p>',true);$('build-close').onclick=closeModal;document.querySelectorAll('[data-site]').forEach(b=>b.onclick=()=>{let d=F.SITES.find(d=>d.id===b.dataset.site);game.waypoint={x:d.x,z:d.z};closeModal();});document.querySelectorAll('[data-machine]').forEach(b=>b.onclick=()=>{if(game.upgradeFactory(b.dataset.machine)){processEvents();save();showFactoryBuildMenu();}else toast('돈이나 정화 결정이 부족해요');});}
function showFactoryRecipes(){showModal('recipes','<div class="eyebrow">생산과 운송</div><h2>무엇으로 무엇을 만들까?</h2><div class="recipe-list"><p>'+iconSVG('raw')+' 먼지 자루 1 → '+iconSVG('material')+' 재생 원료 1</p><p>'+iconSVG('material')+' 원료 3 → '+iconSVG('toy')+' 장난감 1 · 4초</p><p>'+iconSVG('material')+' 원료 5 → '+iconSVG('cloth')+' 옷 1 · 6초</p><p>텃밭 → '+iconSVG('crop')+' 채소 3 · 6초</p><p>'+iconSVG('crop')+' 채소 2 + '+iconSVG('material')+' 포장 원료 1 → '+iconSVG('meal')+' 도시락 1 · 4초</p></div><p>기계 앞 연두 발판은 투입, 옆 발판은 완제품 수거입니다. 중앙선은 창고 → 판매대를 연결합니다. 해당 구역의 지선을 따로 연결하면 기계의 재료와 완제품도 자동 운송됩니다. 손님은 처음부터 재고를 자동 구매합니다. 창구 매니저를 고용하면 구매 처리가 더 빨라집니다. 쌓인 돈은 직접 걷거나 금고와 금색 전용 레일로 자동 수금합니다.</p><p class="smallnote">먼지를 음식으로 바꾸지 않습니다. 음식은 텃밭의 채소로 만들고 재생 원료는 포장에만 씁니다. 정화 결정은 먹는 재료가 아닌 설비 건설·강화 자원입니다.</p>'+btn('recipes-back','알겠어요'));$('recipes-back').onclick=closeModal;}

function showFactoryTools(){showModal('upgrade','<button class="close" id="closemodal" aria-label="닫기">×</button><div class="eyebrow">공방 장비</div><h2>청소와 방어 강화</h2><p>보유 돈 '+game.money+'</p><div class="upgradegrid">'+UPGRADES.map(u=>'<button class="upgrade" data-up="'+u.key+'" '+(game.money<game.upgradeCost(u.key)?'disabled':'')+'><span class="ico">'+u.icon+'</span><b>'+(u.key==='repair'?'마음의 나무':u.name)+'</b><p>'+(u.key==='turret'?'방어탑 공격력 증가 · 진공탑은 설비 강화':u.key==='repair'?'나무 최대 체력 +30 · 전부 회복':u.desc)+'</p><footer><span>Lv. '+game.levels[u.key]+'</span><strong>'+game.upgradeCost(u.key)+'</strong></footer></button>').join('')+'</div><p class="smallnote">기계 속도와 진공탑은 건설 · 강화 메뉴에서 별도로 강화합니다.</p>',true);$('closemodal').onclick=closeModal;document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{if(game.upgrade(b.dataset.up)){processEvents();save();showFactoryTools();updateHUD();}});}
function showExpansionPause(){save();showModal('pause','<div class="eyebrow">'+(game.variant==='tycoon'?'GAME':'STORY')+' · SAVE</div><h2>저장과 설정</h2><p>이 모드의 진행은 따로 저장됩니다.</p><div class="settingline"><span>플레이 시간</span><b>'+formatTime(game.totalTime)+'</b></div>'+btn('resume','계속하기')+'<div class="btnrow">'+btn('export','저장 내보내기','secondary')+btn('import','저장 가져오기','secondary')+'</div>'+btn('restore-backup','이 모드의 시작 전 백업 복원','ghost')+btn('totitle','모드 선택으로','ghost'));$('resume').onclick=closeModal;$('export').onclick=()=>downloadJSON(game.serialize());$('import').onclick=()=>$('importfile').click();$('totitle').onclick=()=>{save();showTitle();};$('restore-backup').onclick=()=>{let data;try{data=localStorage.getItem(STORAGE+'-backup');if(!data){toast('보관된 백업이 없어요');return;}Game.restore(JSON.parse(data));}catch{toast('백업을 읽을 수 없어요');return;}showModal('backupconfirm','<h2>시작 전 백업을 복원할까요?</h2><p>현재 진행도 교체 백업으로 보관합니다.</p>'+btn('backup-cancel','현재 진행 계속하기')+btn('backup-restore','백업 복원','secondary'));$('backup-cancel').onclick=showExpansionPause;$('backup-restore').onclick=()=>{try{localStorage.setItem(STORAGE+'-backup',JSON.stringify(game.serialize()));localStorage.setItem(STORAGE,data);localStorage.removeItem(CHECKPOINT);continueGame();}catch{toast('저장 공간에 쓸 수 없어요');}};};}
// Short, bounded world effects; reward quantities remain engine-owned.
const cleanFX=[];let cleanSoundAt=0;
function cleanSuction(e){if(cleanFX.length>=16)return;let g=group(effects,e.x,.1,e.z);let cloud=group(g);for(let i=0;i<3;i++)sphere(cloud,0x9565df,(i-1)*.28,.23,Math.sin(i)*.15,.42,.3,.38);let rim=ring(g,0xffffff,0,0,.55,.065,.08);let shards=[];if(!reducedMotion)for(let i=0;i<5;i++){let m=box(effects,i%2?0xffffff:0xb780ff,e.x,.6,e.z,.09,.09,.24);shards.push({m,angle:i/5*TAU});}cleanFX.push({g,cloud,rim,shards,x:e.x,z:e.z,age:0});if(!reducedMotion)impact=Math.max(impact,.025);if(visTime-cleanSoundAt>.085){tone(450+Math.min(game.combo,30)*17,.065,'sine',.035);cleanSoundAt=visTime;}}
function renderCleanFX(dt){for(let i=cleanFX.length-1;i>=0;i--){let f=cleanFX[i];f.age+=dt;let t=Math.min(1,f.age/.42);f.cloud.scale.setScalar(Math.max(.01,1-t*2.5));f.rim.scale.setScalar(1+t*2);f.rim.visible=t<.45;for(let s of f.shards){let k=t*t;s.m.position.set(f.x+(game.player.x-f.x)*k+Math.cos(s.angle+t*9)*(1-t)*.45,.4+Math.sin(t*Math.PI)*.9,f.z+(game.player.z-f.z)*k+Math.sin(s.angle+t*9)*(1-t)*.45);s.m.scale.setScalar(1-t*.65);s.m.rotation.y=s.angle+t*8;}if(t>=1){effects.remove(f.g);disposeGroup(f.g);for(let s of f.shards)effects.remove(s.m);cleanFX.splice(i,1);}}}

/* Small live objective + contextual helper in the existing hamburger menu. */
let actionRoot=null,actionViews=[],actionKey='',carriedProp=null,missionDoor=null,missionLight=null;
const questPeek=document.createElement('button');questPeek.id='quest-peek';questPeek.setAttribute('aria-label','다음 목표와 헬퍼 조언 열기');document.body.appendChild(questPeek);questPeek.onclick=()=>{if(running)showQuickMenu();};
function makeMissionProp(icon){let g=new THREE.Group();
 if(['book','bible','menu','letter','document'].includes(icon)){let color=icon==='book'?0x9a77af:icon==='bible'?0x548f7e:0xe2c792;box(g,color,0,.38,0,.8,.16,1);box(g,0xfff5d7,0,.49,0,.69,.07,.91);if(icon==='bible'){box(g,0xe0b663,0,.54,0,.08,.015,.55);box(g,0xe0b663,0,.54,-.12,.34,.015,.08);}else{for(let z of [-.2,0,.2])box(g,0xa5ad9f,0,.535,z,.45,.01,.035);}}
 else if(icon==='portrait'){box(g,0xcfae69,0,.85,0,1.1,1.5,.2);box(g,0xf6ecd6,0,.86,.12,.88,1.27,.04);sphere(g,0xac8767,0,1.06,.19,.2,.23,.045);box(g,0x94af9d,0,.62,.17,.45,.4,.07);}
 else if(icon==='key'){ring(g,0xeac35d,0,0,.24,.08,.45);box(g,0xeac35d,0,.45,.4,.13,.1,.55);box(g,0xeac35d,.13,.45,.58,.28,.1,.11);}
 else if(icon==='bin'){box(g,0x648677,0,.45,0,1.5,.9,1.3);box(g,0x254e42,0,.92,0,1.25,.04,1.05);}
 else if(icon==='shelf'){box(g,0xb59566,0,.8,0,2,1.6,.65);box(g,0x5e756a,0,.9,.35,1.75,1.2,.08);for(let y of [.3,.9,1.5])box(g,0xe3d0a8,0,y,.5,1.85,.1,.8);}
 else if(icon==='pipe'){cyl(g,0x618c82,0,.4,0,.65,.45);let arrow=textPlane('➜',1,'#fff1c7');arrow.position.y=.66;g.add(arrow);g.userData.arrow=arrow;}
 else if(icon==='lamp'){cyl(g,0xb69e72,0,.7,0,.07,1.25);let light=sphere(g,0xffe8a1,0,1.5,0,.4);g.userData.lamp=light;}
 else if(icon==='friend'){cyl(g,0xefddb8,0,.65,0,.32,1.2);sphere(g,0xe5c29c,0,1.45,0,.25);sphere(g,0x897663,0,1.6,-.04,.26,.14,.24);ring(g,0xffe7a3,0,0,1,.04,.2);}
 else if(icon==='table'){box(g,0xdab580,0,.8,0,1.6,.16,1.2);for(let x of [-.6,.6])box(g,0x9c8668,x,.4,0,.12,.8,.8);}
 else if(icon==='bed'){box(g,0xc1a578,0,.3,0,1.5,.5,2);box(g,0xf4e7c9,0,.63,0,1.5,.17,2);sphere(g,0xfffaf0,0,.8,-.6,.5,.13,.35);}
 else if(icon==='dust'){for(let i=0;i<3;i++)sphere(g,0x796487,(i-1)*.4,.4,Math.sin(i)*.3,.65,.45,.6);}
 else if(['gift','box','tool','clock'].includes(icon)){box(g,icon==='box'?0x9c8971:0xc3a466,0,.5,0,.95,.8,.85);box(g,0xf4e5c3,0,.92,0,.17,.04,.9);if(icon==='tool')box(g,0x567d78,0,1.05,0,1.25,.18,.23);}
 else if(['crop','meal','cloth'].includes(icon)){let ico=productIcon(icon,1.25);ico.position.y=.4;g.add(ico);box(g,0xe5d7b5,0,.23,0,1.2,.3,1.2);}
 else {let ico=textPlane(({heart:'♡',star:'★',moon:'☾',music:'♫'})[icon]||'◇',1.3,'#65947d');ico.position.y=.37;g.add(ico);}
 return g;}
function buildActionViews(){if(actionRoot?.parent){actionRoot.parent.remove(actionRoot);disposeGroup(actionRoot);}actionRoot=group(environment);actionRoot.userData.dynamic=true;actionViews=[];carriedProp=null;missionDoor=null;missionLight=null;let a=game.actionState(),d=game.actionDef();actionKey=game.chapter+':'+a.step;if(!d)return;
 for(let n of game.actionObjects()){let g=group(actionRoot,n.x,0,n.z),base=cyl(g,n.role==='target'?0xf1d388:0xc7e1d1,0,.23,0,n.role==='target'?1.2:1,.16),rim=ring(g,0xfff5d6,0,0,1.1,.06,.33),prop=makeMissionProp(n.icon);g.add(prop);let label=textPlane(n.role==='target'?'↓':String(n.index+1),.62,n.role==='target'?'#9b751c':'#437a69');label.position.set(0,.34,1.1);g.add(label);actionViews.push({n,g,base,rim,prop,label});}
 if(d.type==='carry'){carriedProp=makeMissionProp(d.sources[0].icon);carriedProp.scale.setScalar(.7);actionRoot.add(carriedProp);}
 if(d.type==='trust'){let closet=group(actionRoot,0,0,-6);box(closet,0x89765d,0,1.5,0,3,3,1.3);missionDoor=group(closet,-1.4,0,.7);box(missionDoor,0xc7b288,1.4,1.5,0,2.8,2.8,.14);sphere(missionDoor,0x876939,2.5,1.4,.12,.1);missionLight=sphere(actionRoot,0xffe7a3,8,.8,-6,.4);}
}
function renderActionViews(dt){let a=game.actionState(),d=game.actionDef();if(actionKey!==game.chapter+':'+a.step||!actionRoot?.parent)buildActionViews();let target=game.actionTarget(),n=game.puzzleNear(),progress=game.actionProgress();for(let v of actionViews){let state=game.actionObjects().find(q=>q.id===v.n.id);v.g.visible=!!state?.active||v.n.role==='target';let active=target?.id===v.n.id;v.rim.material=mat(active?0xffca5e:0xe3e9d8);v.rim.scale.setScalar(active?1+.09*Math.sin(visTime*4):1);
 if(d.type==='rotate')v.prop.userData.arrow.rotation.z=-(a.orient[v.n.index]-1)*Math.PI/2;
 if(d.type==='lights')v.prop.userData.lamp.material=mat(a.lights[v.n.index]?0xffe69a:0x75877d);
 if(d.type==='memory'){let lit=a.phase==='watch'&&a.clock<4&&d.sequence[Math.floor(a.clock)]===v.n.index&&a.clock%1<.75;v.base.material=mat(lit?0xffca5e:a.phase==='input'?0x98c7b2:0xc7d5cc);}
 if(d.type==='rhythm'){let beat=a.clock%2>=.65&&a.clock%2<=1.4;v.base.material=mat(beat?0x52bd89:0xd8c7ab);v.rim.scale.setScalar(.9+(a.clock%2)/2*.25);}
 if(d.type==='sweep')v.prop.scale.setScalar(Math.max(.05,a.hp[v.n.index]/2));
 }
 if(carriedProp){carriedProp.visible=a.carrying>=0;carriedProp.position.set(game.player.x+.45,1.1,game.player.z+.35);carriedProp.rotation.y=game.player.angle;}
 if(missionDoor){missionDoor.rotation.y=-Math.min(1,a.hold/6)*1.8;missionLight.position.set(8*(1-Math.min(1,a.hold/3)),1+.3*Math.sin(visTime*3),-6);}
 const done=!d&&!game.journey.ending;$('interactpanel').classList.toggle('visible',running&&(!!n||done));document.body.classList.toggle('near-puzzle',running&&!!n);if(n){$('interact').textContent=n.label+(n.passive?' · '+progress.value+'/'+progress.max:'');$('interact').disabled=n.passive;$('interact').classList.toggle('beat-ready',d.type==='rhythm'&&a.clock%2>=.65&&a.clock%2<=1.4);if(d.type==='rhythm')$('interact').textContent=(a.clock%2>=.65&&a.clock%2<=1.4?'지금! · ':'기다려요 · ')+'박자 맞추기 '+a.count+'/3';$('interact-title').textContent=d.title;}else if(done){$('interact').textContent=game.chapter===7?'명의 이전 서명으로':'미션 완료 · 다음 방';$('interact').disabled=false;}
}
