showJourneyComplete=function(){let i=game.chapter,b=CleanHouse.STORY_BOOK[CleanHouse.language][i];if(i===7){showModal('deed','<div class="eyebrow">'+say('마지막 약속','OUR PROMISE')+'</div><h2>'+say('예수님께<br>이 집을 맡겨요.','Jesus, I trust you<br>with this home.')+'</h2><div class="deed"><h3>'+say('명의 이전','Giving the house')+'</h3><p>'+say('예수님, 제 마음의 모든 방과<br>모든 열쇠를 드려요.<br>매일 예수님과 함께 살고 싶어요.','Jesus, I give you every room<br>and every key of my heart.<br>I want to live with you each day.')+'</p><span class="stamp">'+say('믿고<br>맡겨요','With<br>trust')+'</span></div>'+btn('sign',say('서명하고 집을 맡기기','Sign and give the house')));$('sign').onclick=()=>{game.signDeed();game.enemies=[];save();showModal('ending','<div class="eyebrow">'+say('이야기를 마쳤어요','THE END · A NEW BEGINNING')+'</div><h2>'+say('이제 함께 사는 집이에요.','Now we live here together.')+'</h2><p>'+say('모든 일을 잘해서 드린 집이 아니에요. 예수님을 믿고 맡겼어요. 내일도 함께 걸어요.','I did not give this house because I did everything perfectly. I gave it because I trust Jesus. Tomorrow, we will walk together again.')+'</p>'+btn('story-rest',say('집에서 쉬기','Rest in the house'))+btn('modes',say('모드 선택으로','Choose a mode'),'secondary'));$('story-rest').onclick=closeModal;$('modes').onclick=()=>{save();showTitle();};};return;}showModal('complete','<div class="eyebrow">'+b[0]+'</div><h2>'+say('한 방을 함께 돌봤어요.','We cared for a room together.')+'</h2><p>'+b[1]+'.</p>'+btn('next',say('다음 이야기 펼치기 →','Open the next chapter →')));$('next').onclick=()=>{game.next();buildEnvironment();setCheckpoint();showJourneyStory();};};
