const vividExpansion=renderExpansion;renderExpansion=function(dt){vividExpansion(dt);renderVividFX(dt);if(game.variant!=='journey')return;let s=game.ensureStoryGuard();for(let v of lampViews){let target=s.paid[v.i]/game.storyLampCost(v.i);v.display=(v.display||0)+(target-(v.display||0))*Math.min(1,dt*9);let fraction=v.display;v.ghost.visible=!s.built[v.i];v.fill.scale.y=Math.max(.03,fraction*2.2);v.fill.position.y=.4+fraction*1.1;v.label.innerHTML='<b>☼ '+(v.i+1)+(s.levels[v.i]?' · Lv.'+s.levels[v.i]:'')+'</b><span>'+s.paid[v.i]+'/'+game.storyLampCost(v.i)+'</span>';v.label.style.display=running&&Math.hypot(v.p.x-game.player.x,v.p.z-game.player.z)<17?'':'none';placeTag(v.label,v.p.x,s.built[v.i]?4.1:3.2,v.p.z);let m=stationVisuals.get('built-story-lamp-'+v.i);if(m?.userData.fill){m.userData.fill.scale.y=Math.max(.01,fraction*1.6);m.userData.fill.position.y=.45+fraction*.8;m.userData.crystal.scale.setScalar(.95+(reducedMotion?0:Math.sin(visTime*4)*.05));}}};

