function batchFrontierScenery(root){root.updateMatrixWorld(true);let buckets=new Map(),remove=[];root.traverse(m=>{if(!m.isMesh||!Object.values(geometries).includes(m.geometry))return;let key=m.geometry.uuid+'_'+m.material.uuid;if(!buckets.has(key))buckets.set(key,{geo:m.geometry,mat:m.material,items:[]});buckets.get(key).items.push(m.matrixWorld.clone());remove.push(m);});for(let m of remove)m.removeFromParent();for(let b of buckets.values()){let inst=new THREE.InstancedMesh(b.geo,b.mat,b.items.length);b.items.forEach((m,i)=>inst.setMatrixAt(i,m));inst.castShadow=true;inst.receiveShadow=true;root.add(inst);}}
