const frontierEvents=handleExpansionEvent;handleExpansionEvent=function(e){frontierEvents(e);if(e.type==='rich_clean'){burst(e.x,e.z,e.crystal?0xff36cf:0xb57aff,12);floatReward(e.crystal?'◆ +1':'+4',e.x,e.z,e.crystal?'core':'');}if(e.type==='treasure'){burst(e.x,e.z,['jam','ambush'].includes(e.outcome)?0xff3651:0xffc400,26);addPulse(e.x,e.z,0xffbd00);tone(['jam','ambush'].includes(e.outcome)?180:880,.4);toast(e.text);save();}if(e.type==='dispatch'){flyResources(e.x,e.z,e.n,colors.raw);floatReward('↑ '+e.n,e.x,e.z);toast('자루 '+e.n+'개가 중앙 재활용기에 도착했어요');save();}if(e.type==='express_depart'){addPulse(e.x,e.z,0x2dcfff);toast('급행 카트 출발!');}if(e.type==='express'){addPulse(e.x,e.z,0x2dcfff);toast('급행 카트로 공방에 돌아왔어요');save();}if(e.type==='frontier_discovery'){toast(e.name+' 발견!');save();}if(e.type==='resource_surge')toast(e.name+' · 큰 먼지 풍년!');if(e.type==='contract_done'){toast('단체 주문 완료! 돈 +'+e.reward+' · 결정 +'+e.cores);tone(980,.4);save();}if(e.type==='market_bonus')floatReward('+'+e.n,e.x,e.z,'gold');};
function frontierMapSVG(){let s=game.factory.frontier;return '<svg class="frontier-map" viewBox="-94 -94 188 188" role="img" aria-label="북쪽 결정, 동쪽 장난감, 남쪽 정원, 서쪽 의류 지도"><rect x="-90" y="-90" width="180" height="180" rx="8" fill="#172b42"/><path d="M-80 0H80M0-80V80" stroke="#425c74" stroke-width="6"/>'+CleanHouse.FRONTIER.regions.map(r=>'<rect x="'+(r.x-20)+'" y="'+(r.z-20)+'" width="40" height="40" rx="5" fill="#'+r.color.toString(16)+'" opacity=".8"/><text x="'+r.x+'" y="'+r.z+'" text-anchor="middle" fill="white" font-size="7">'+['결정','장난감','정원','의류'][r.id]+'</text>').join('')+'<rect x="-27" y="-22" width="54" height="44" rx="4" fill="#c6d4dc"/><text x="0" y="2" text-anchor="middle" font-size="8" fill="#14283e">공방</text>'+(game.factory.sites.rail.built?'<polyline points="'+game.railPoints().map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#ffde54" stroke-width="1.8"/>':'')+s.chests.map(c=>'<text x="'+c.x+'" y="'+c.z+'" fill="#ffed6c" font-size="11" text-anchor="middle">◆</text>').join('')+game.enemies.map(e=>'<circle cx="'+e.x+'" cy="'+e.z+'" r="1.6" fill="#ff3955"/>').join('')+'<circle cx="'+game.player.x+'" cy="'+game.player.z+'" r="3" fill="#fff" stroke="#09a9d7" stroke-width="2"/></svg>';}
function showFrontierMap(){let s=game.ensureFrontier(),f=game.factory,o=game.contractOffer(),c=s.contract;showModal('frontier','<button class="close" id="frontier-close" aria-label="닫기">×</button><div class="eyebrow">EXPLORE · BUILD · DEFEND</div><h2>사방으로, 더 멀리</h2>'+frontierMapSVG()+'<div class="frontier-destinations">'+CleanHouse.FRONTIER.regions.map(r=>'<button data-region="'+r.id+'">'+r.name+'<small>'+ (s.discovered[r.id]?'발견함':'탐험하기')+' →</small></button>').join('')+'<button id="frontier-home">⌂ 중앙 공방 →</button></div><div class="frontier-contract"><b>단체 주문</b><p>'+(c?F.GOODS[c.kind].name+' '+Math.min(c.goal,s.sold[c.kind]-c.start)+' / '+c.goal+' · 남은 '+Math.ceil(c.left)+'초':F.GOODS[o.kind].name+' '+o.goal+'개 · 180초')+'</p><small>판매대에서 실제 판매하면 집계됩니다. 완료 시 돈 '+(c||o).reward+' · 결정 '+(c||o).cores+'. 실패 시 평판 −4.</small>'+(!c?'<button id="accept-contract" '+(s.contractCooldown>0?'disabled':'')+'>'+(s.contractCooldown>0?Math.ceil(s.contractCooldown)+'초 뒤 새 주문':'주문 받기')+'</button>':'')+'</div><p>지금 '+F.GOODS[F.LANES[s.market].kind].name+' 판매가 +30% · '+Math.ceil(90-game.totalTime%90)+'초 남음</p><p class="smallnote">큰 먼지에서 자루 +4, 북쪽 분홍 먼지에서 결정 +1. 거점에 서서 자루를 보내세요. 해당 구역의 지선을 연결하면 자동 운송과 급행 귀환이 열립니다.</p><details><summary>보물상자 · 보상과 위험</summary><p>돈 35% · 결정 20% · 25초 가속 20% · 세균 3마리 매복 15% · 생산 6초 정지와 수리비 10%. 수리비는 보유 돈 10%, 최대 50입니다. 상자는 무료로 열며, 열지 않아도 됩니다. 결과는 상자가 생길 때 결정되고 저장됩니다.</p></details>'+btn('frontier-machines','설비 · 물류 강화','secondary'));let policy=document.createElement('div');policy.className='frontier-policy';policy.innerHTML='<b>레일 원료 배분</b><div>'+[['balanced','균형'],['production','생산 우선'],['trade','원료 판매 우선']].map(([id,label])=>'<button data-policy="'+id+'" aria-pressed="'+(s.policy===id)+'">'+label+'</button>').join('')+'</div><small>생산 우선은 원료 60개를 생산용으로 남기고, 판매 우선은 판매대 40개를 먼저 채웁니다. 레일 건설 후 적용됩니다.</small>';$('frontier-machines').before(policy);policy.querySelectorAll('button').forEach(b=>b.onclick=()=>{s.policy=b.dataset.policy;save();showFrontierMap();});$('frontier-close').onclick=closeModal;document.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{let r=CleanHouse.FRONTIER.regions[+b.dataset.region];game.waypoint={x:r.x,z:r.z};closeModal();});$('frontier-home').onclick=()=>{game.waypoint={x:0,z:6};closeModal();};$('frontier-machines').onclick=showFactoryBuildMenu;if($('accept-contract'))$('accept-contract').onclick=()=>{game.acceptContract();save();showFrontierMap();};}
const frontierMenu=showQuickMenu;showQuickMenu=function(){frontierMenu();if(game.variant==='tycoon'&&modalKind==='menu'){let b=document.createElement('button');b.id='menu-frontier';b.textContent='⌖ 탐험 지도 · 단체 주문';b.onclick=showFrontierMap;document.querySelector('.quick-grid')?.prepend(b);}};
showFactoryBuildMenu=function(){let f=game.factory;showModal('buildmenu','<button class="close" id="build-close" aria-label="닫기">×</button><div class="eyebrow">돈 '+game.money+' · 결정 '+f.cores+'</div><h2>생산 · 물류 · 방어</h2><div class="factory-build-list">'+F.SITES.filter(d=>game.factoryUnlocked(d)).map(d=>{let s=f.sites[d.id],up=s.built&&(F.RECIPES[d.kind]||['vacuum','rail','clerk','tower'].includes(d.kind)),o=game.frontierUpgradeOffer(d.id),effect=d.kind==='rail'?'운송량·빈도·카트 속도 증가':d.kind==='clerk'?'판매 처리 속도 증가':d.kind==='tower'?'방어 피해 +8':d.kind==='vacuum'?'채취량·공격력 증가':'생산 속도 +40%';return '<div><button data-site="'+d.id+'"><b>'+d.name+(s.built?' Lv.'+s.level:'')+'</b><small>'+(s.built?effect:'돈 '+(d.cost-s.paid)+' · 결정 '+d.cores)+' → 위치</small></button>'+(up?'<button class="machine-up" data-machine="'+d.id+'" '+(s.level>=8?'disabled':'')+'>'+(s.level>=8?'MAX':'강화<br>'+o.money+' / ◆'+o.cores)+'</button>':'')+'</div>';}).join('')+'</div><p class="smallnote">발판에서 건설 · 메뉴에서 강화. 기계 8레벨까지. 구역 지선을 연결한 기계만 재료·완제품이 자동 운송됩니다.</p>',true);$('build-close').onclick=closeModal;document.querySelectorAll('[data-site]').forEach(b=>b.onclick=()=>{let d=F.SITES.find(d=>d.id===b.dataset.site);game.waypoint={x:d.x,z:d.z};closeModal();});document.querySelectorAll('[data-machine]').forEach(b=>b.onclick=()=>{if(game.upgradeFactory(b.dataset.machine)){processEvents();save();showFactoryBuildMenu();}else toast('돈이나 결정이 부족해요');});};
const factoryIntroOld=showFactoryIntro;showFactoryIntro=function(){factoryIntroOld();let p=document.createElement('p');p.className='smallnote';p.textContent='사방의 외곽에서 큰 먼지·결정을 찾아보세요. 탐험 지도에서 단체 주문을 받고 금색 보물상자를 발견할 수 있어요. 상자는 25% 확률로 함정이 있으니 직접 선택해 열어요.';$('factory-go').before(p);};

