const frontierCrystals=new THREE.InstancedMesh(geometries.box,mat(0xff63df),720);frontierCrystals.frustumCulled=false;frontierCrystals.castShadow=true;actors.add(frontierCrystals);const renderFrontierCrystals=renderExpansion;renderExpansion=function(dt){renderFrontierCrystals(dt);frontierCrystals.visible=game.variant==='tycoon';if(!frontierCrystals.visible)return;let list=game.dirt.filter(d=>d.rich===2&&Math.hypot(d.x-game.player.x,d.z-game.player.z)<30);frontierCrystals.count=list.length;for(let i=0;i<list.length;i++){let d=list[i];dummy.position.set(d.x,.9,d.z);dummy.scale.set(.24,.55,.24);dummy.rotation.set(.2,.4,.35);dummy.updateMatrix();frontierCrystals.setMatrixAt(i,dummy.matrix);}frontierCrystals.instanceMatrix.needsUpdate=true;};

