function createBaseNexus(parent){let g=group(parent,0,0,2);g.userData.dynamic=true;let parts=[];cyl(g,0x12263f,0,.38,0,3.5,.7);cyl(g,0x255b72,0,.85,0,2.8,.5);ring(g,0xffc631,0,0,3.45,.18,.8);cyl(g,0x17304d,0,2.3,0,1.1,3);for(let i=0;i<6;i++){let a=i/6*TAU,x=Math.cos(a)*2.1,z=Math.sin(a)*2.1;let p=group(g,x,0,z);box(p,0x263f60,0,1.4,0,.65,2.4,.65);let crown=box(p,0xffca37,0,3,0,.75,.8,.75);crown.rotation.z=.2;parts.push(p);}let crystal=group(g,0,4.2,0);let c=box(crystal,0x24e1ce,0,0,0,1.7,2.8,1.7);c.rotation.set(.12,Math.PI/4,.16);box(crystal,0xbaffff,0,.25,.85,.38,1.8,.1);let cap=box(g,0xffc13a,0,6.3,0,.8,.9,.8);cap.rotation.z=Math.PI/4;heart=sphere(g,0xffe789,0,4.2,1.25,.4);halo=ring(g,0x28ebdb,0,0,4,.16,.22);let cracks=group(g);for(let i=0;i<5;i++){let m=box(cracks,0xff304f,(i-2)*.35,1.35+i*.36,1.12,.13,.65,.09);m.rotation.z=i%2?.7:-.5;}let rubble=group(g);for(let i=0;i<7;i++){let a=i/7*TAU,m=box(rubble,0x23384e,Math.cos(a)*3,.6,Math.sin(a)*3,.55,.45,.6);m.rotation.z=i*.6;}opsNexus={g,crystal,parts,cracks,rubble};opsLastHP=game.baseHP;factoryLabel(0,2,'nexus','nexus');}
