function buildSectionRails(parent){parent.userData.railEdges=new Set();let o=game.baseOps();for(let l of OPS.LINES){if(!game.lineActive(l.id))continue;drawOpsRail(parent,l.points,l.color);if(o.buildings.bank.built&&o.lines[l.id].moneyBuilt){let d=OPS.BUILDINGS.find(d=>d.line===l.id);drawOpsRail(parent,game.moneyRoute(l.id,d.x,d.z),0xffcb2f,true);}let end=l.points.at(-1);cyl(parent,l.color,end[0],.24,end[1],1,.2);for(let d of F.SITES){if(game.siteLine(d)!==l.id||!game.factory.sites[d.id].built||!F.RECIPES[d.kind])continue;let route=game.routeTo(l.id,d.x,d.z+2);drawOpsRail(parent,route.slice(-3),l.color);let out=game.routeTo(l.id,d.x+2,d.z);drawOpsRail(parent,out.slice(-3),l.color);}}if(o.buildings.bank.built){drawOpsRail(parent,[[-10.2,13.2],[19,13.2],[19,6]],0xffcb2f,true);for(let d of F.LANES)drawOpsRail(parent,[[d.x+1.8,12],[d.x+1.8,13.2]],0xffcb2f,true);}}
