function showUpgradeInfo(id){let d=F.SITES.find(d=>d.id===id),s=game.factory.sites[id],offer=game.instantUpgradeOffer(id);showModal('upgrade-info','<button class="close" id="ops-close">×</button><div class="eyebrow">UPGRADE BENEFIT</div><h2>'+d.name+' Lv.'+s.level+'</h2><div class="ops-benefit">'+(s.level>=8?'최대 레벨을 달성했어요.':game.upgradeBenefits(id).join('<br>'))+'</div>'+(s.level<8?'<p>현장 강화 · 돈 '+offer.money+' · 정화 결정 '+offer.cores+'</p><p>즉시 강화 수수료 · 돈 '+offer.fee+' <small>(남은 돈 비용의 20%, 최소 10)</small></p><p><b>즉시 강화 총액 · 돈 '+offer.payMoney+' · 정화 결정 '+offer.cores+'</b><br>보유 · 돈 '+Math.floor(game.money)+' · 정화 결정 '+game.factory.cores+'</p>'+btn('ops-upgrade','돈 '+offer.payMoney+' + 결정 '+offer.cores+' 지불 · 즉시 강화'):'')+btn('ops-pad','수수료 없이 · 현장 강화 발판으로','secondary'));$('ops-close').onclick=closeModal;$('ops-pad').onclick=()=>{game.waypoint=game.fieldUpgradePad(id);closeModal();};if($('ops-upgrade')){let b=$('ops-upgrade');b.disabled=game.money<offer.payMoney||game.factory.cores<offer.cores;if(b.disabled)b.textContent='부족 · 돈 '+Math.max(0,offer.payMoney-game.money)+' / 결정 '+Math.max(0,offer.cores-game.factory.cores);b.onclick=()=>{let paid=game.instantUpgradeOffer(id);if(game.instantUpgradeFactory(id)){processEvents();save();showUpgradeInfo(id);toast('강화 완료 · 돈 −'+paid.payMoney+' · 결정 −'+paid.cores+' (수수료 '+paid.fee+' 포함)');}else toast('돈이나 결정이 부족해요');};}}
