function drawRadar(canvas){let ctx=canvas.getContext('2d'),w=canvas.width,s=w/188,o=game.baseOps();ctx.clearRect(0,0,w,w);ctx.fillStyle='#0b1c30';ctx.fillRect(0,0,w,w);ctx.save();ctx.translate(w/2,w/2);ctx.scale(s,s);ctx.strokeStyle='#23415d';ctx.lineWidth=.7;for(let r of [25,50,75,90]){ctx.beginPath();ctx.arc(0,0,r,0,TAU);ctx.stroke();}ctx.beginPath();ctx.moveTo(-94,0);ctx.lineTo(94,0);ctx.moveTo(0,-94);ctx.lineTo(0,94);ctx.stroke();for(let r of CleanHouse.FRONTIER.regions){ctx.fillStyle='#'+r.color.toString(16)+'40';ctx.fillRect(r.x-18,r.z-18,36,36);}for(let d of game.dirt){ctx.fillStyle=d.rich===2?'#ff64d9':'#9976d0';ctx.fillRect(d.x-.65,d.z-.65,1.3,1.3);}for(let l of OPS.LINES){if(!game.lineActive(l.id))continue;ctx.strokeStyle='#'+l.color.toString(16);ctx.lineWidth=1.5;ctx.beginPath();l.points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}if(o.buildings.bank.built){ctx.strokeStyle='#ffd136';ctx.beginPath();ctx.moveTo(-10,13.2);ctx.lineTo(19,13.2);ctx.lineTo(19,6);ctx.stroke();}let dot=(x,z,c,r)=>{ctx.fillStyle=c;ctx.beginPath();ctx.arc(x,z,r,0,TAU);ctx.fill();};for(let l of OPS.LINES)if(o.lines[l.id].moneyBuilt){let d=OPS.BUILDINGS.find(d=>d.line===l.id);ctx.strokeStyle='#ffce38';ctx.lineWidth=.7;ctx.beginPath();game.moneyRoute(l.id,d.x,d.z).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}for(let d of F.SITES){ctx.fillStyle=game.factory.sites[d.id].built?'#ddf7ff':'#526780';ctx.fillRect(d.x-1.4,d.z-1.4,2.8,2.8);}for(let d of OPS.BUILDINGS){ctx.fillStyle=o.buildings[d.id].built?'#36e9d7':'#63708a';ctx.fillRect(d.x-2,d.z-2,4,4);}for(let c of game.factory.frontier.chests){ctx.fillStyle='#ffd33a';ctx.fillRect(c.x-1.8,c.z-1.8,3.6,3.6);}for(let e of game.enemies){dot(e.x,e.z,'#ff304f',e.boss?3:1.8);if(e.boss){ctx.strokeStyle='#fff';ctx.stroke();}}dot(0,2,game.baseHP/game.baseMax<.3?'#ff345b':'#fff0a2',3.4);if(game.waypoint){ctx.strokeStyle='#63ffbc';ctx.lineWidth=1.2;ctx.beginPath();ctx.moveTo(game.player.x,game.player.z);ctx.lineTo(game.waypoint.x,game.waypoint.z);ctx.stroke();dot(game.waypoint.x,game.waypoint.z,'#63ffbc',2);}dot(game.player.x,game.player.z,'#fff',2.9);ctx.strokeStyle='#00bfff';ctx.lineWidth=1.5;ctx.stroke();ctx.restore();ctx.fillStyle='#d8edff';ctx.font='bold 16px sans-serif';ctx.fillText('N',w/2-5,18);}
const oldFrontierMap=showFrontierMap;showFrontierMap=function(){if(!game.baseOps().buildings.radar.built){showBaseBuilding('radar');return;}oldFrontierMap();let svg=document.querySelector('.frontier-map'),canvas=document.createElement('canvas');canvas.id='ops-large-map';canvas.width=canvas.height=640;canvas.setAttribute('aria-label','실시간 전체 기지 지도');svg.replaceWith(canvas);drawRadar(canvas);canvas.onclick=e=>{let b=canvas.getBoundingClientRect();game.waypoint={x:Math.max(-88,Math.min(88,(e.clientX-b.left)/b.width*188-94)),z:Math.max(-88,Math.min(88,(e.clientY-b.top)/b.height*188-94))};closeModal();};let legend=document.createElement('div');legend.className='radar-legend';let types={dust:'기본',runner:'돌진',tank:'탱크',split:'분열',healer:'회복',spitter:'원거리',boss:'보스'},counts=Object.entries(types).map(([k,n])=>{let q=game.enemies.filter(e=>e.kind===k).length;return q?n+' '+q:null;}).filter(Boolean);legend.innerHTML='<b>흰 점 나 · 노랑 넥서스/상자 · 빨강 세균<br>하얀 사각 건물 · 보라 먼지 · 분홍 결정</b><p>세균: '+(counts.join(' · ')||'없음')+'</p><small>지도를 눌러 목적지를 표시하세요. 메뉴를 닫으면 실시간 스캔이 계속됩니다.</small>';canvas.after(legend);let b=document.createElement('button');b.className='btn secondary';b.textContent='⚒ 구역 연결 · 기지 확장';b.onclick=showBaseNetwork;legend.after(b);};
const opsEvents=handleExpansionEvent;handleExpansionEvent=function(e){opsEvents(e);if(e.type==='network_build'){buildEnvironment();save();spawnVividFX('build',{x:e.x,z:e.z});benefitNotice('✓ '+e.name,[e.benefit]);tone(930,.3);}if(e.type==='factory_build'&&e.fieldUpgrade)benefitNotice(e.name+' 강화 완료',game.upgradeBenefits(e.id,e.level-1));if(e.type==='bank_deposit'){statKick('money');if(Math.hypot(game.player.x-19,game.player.z-6)<15)floatReward('+'+e.n,19,6,'gold');}if(e.type==='story_shelter')benefitNotice(say('보호등','Shelter lamp')+' Lv.'+e.level,[say('광선 공격력 ','Beam damage ')+(18+e.level*6)+say(' · 사거리 9.5',' · Range 9.5'),say('근처에서 초당 체력 4 회복','Recover 4 HP/sec nearby')]);if(e.type==='damage'&&e.target==='base'){opsHit=.45;spawnVividFX('wrong',{x:0,z:2});if(!reducedMotion)impact=Math.max(impact,.08);}if(e.type==='upgrade'){let u=UPGRADES.find(u=>u.key===e.key);benefitNotice(u.name+' Lv.'+game.levels[e.key],[u.desc]);}};
function packetPosition(p){let a=p.path[p.segment],b=p.path[Math.min(p.segment+1,p.path.length-1)],len=Math.hypot(b[0]-a[0],b[1]-a[1]),t=len?Math.min(1,p.progress/len):0;return {x:a[0]+(b[0]-a[0])*t,z:a[1]+(b[1]-a[1])*t,angle:Math.atan2(b[0]-a[0],b[1]-a[1])};}
const opsRender=renderExpansion;renderExpansion=function(dt){opsRender(dt);if(performance.now()>opsNoticeUntil)opsNotice.hidden=true;let active=game.variant==='tycoon';radar.hidden=!active||!running||!game.baseOps().buildings.radar.built;opsNotice.style.display=modalKind==='title'?'none':'';if(!active)return;let o=game.baseOps();frontierMapButton.innerHTML='<b>⌖ '+(o.buildings.radar.built?'전체 지도':'관측소 건설')+'</b><small>⚒ 구역 레일 · 기지 확장</small>';if(opsNexus){let hp=game.baseHP/game.baseMax;opsHit=Math.max(0,opsHit-dt);opsNexus.g.rotation.z=reducedMotion?0:Math.sin(visTime*65)*opsHit*.035;opsNexus.crystal.rotation.y=Math.sin(visTime*.8)*.12;opsNexus.crystal.children[0].material=mat(opsHit>0?0xff3455:hp<.3?0xc43d53:hp<.65?0xe59b29:0x24e1ce);opsNexus.cracks.visible=hp<.65;opsNexus.rubble.visible=hp<.4;opsNexus.parts.forEach((p,i)=>{p.rotation.z=hp<.4&&i%2?.45:0;p.children[1].visible=hp>.2||i%2===0;});heart.position.y=4.2+Math.sin(visTime*2)*.09;halo.material=mat(hp<.3?0xff3455:0x24e1ce);halo.scale.setScalar(1+(hp<.3?Math.sin(visTime*8)*.04:0));let label=factoryLabels.find(l=>l.kind==='nexus');if(label){label.el.innerHTML='<strong>◆ 넥서스</strong><span>'+Math.ceil(game.baseHP)+' / '+game.baseMax+'</span><i style="width:'+Math.max(0,hp*100)+'%"></i>';label.el.classList.toggle('critical',hp<.3);placeTag(label.el,0,7.5,2);}}
 for(let v of growthViews){if(v.el.querySelector('.ops-info'))continue;let b=document.createElement('button');b.className='ops-info';b.textContent='!';b.setAttribute('aria-label',F.SITES.find(d=>d.id===v.id).name+' 강화 효과');b.onclick=()=>showUpgradeInfo(v.id);v.el.appendChild(b);}
 for(let v of opsLabels){let s=o.buildings[v.d.id],near=Math.hypot(game.player.x-v.d.x,game.player.z-v.d.z);v.el.hidden=!running||near>17;let state=s.built?(v.d.line?'재고 '+s.stock+' · ¤ '+s.cash:'✓ 가동 중'):opsCosts(v.d);v.el.innerHTML='<b>'+v.d.icon+' '+v.d.name+' <em>!</em></b><small>'+state+'</small>';placeTag(v.el,v.d.x,s.built?4.5:3.4,v.d.z);}
 for(let p of o.packets){let m=opsPackets.get(p.id);if(!m){m=group(actors);box(m,0x162d45,0,.45,0,.95,.25,1.2);box(m,p.kind==='money'?0xffc928:colors[p.kind],0,.75,0,.68,.42,.8);for(let x of [-.5,.5])sphere(m,0x23374e,x,.27,0,.16);opsPackets.set(p.id,m);}let pos=packetPosition(p);m.position.set(pos.x,0,pos.z);m.rotation.y=pos.angle;m.visible=Math.hypot(pos.x-game.player.x,pos.z-game.player.z)<40;}
 for(let [id,m]of opsPackets)if(!o.packets.some(p=>p.id===id)){m.removeFromParent();disposeGroup(m);opsPackets.delete(id);}
 let guests=OPS.BUILDINGS.flatMap(d=>o.buildings[d.id].visitors.map(v=>({...v,color:d.region==null?0x44dbe0:CleanHouse.FRONTIER.regions[d.region].color})));while(opsGuests.length<guests.length){let g=group(actors);cyl(g,0x299cca,0,.75,0,.27,.8);sphere(g,0xf4cdac,0,1.38,0,.28);box(g,0x172d44,0,.23,0,.36,.4,.25);opsGuests.push(g);}opsGuests.forEach((g,i)=>{g.visible=i<guests.length;if(g.visible){let v=guests[i];g.position.set(v.x,Math.abs(Math.sin(visTime*10+i))*.06,v.z);g.children[0].material=mat(v.color);}});
 // Only the player's occupied cart is drawn; cargo carts are driven by real shipments.
 if(factoryCart&&!game.factory.railRide&&!game.factory.frontier.express)factoryCart.visible=false;
 opsRadarClock-=dt;if(opsRadarClock<=0){opsRadarClock=.2;if(!radar.hidden)drawRadar(radar.querySelector('canvas'));}
};

/* Civic UI, distinct facilities and an earned visual progression for the whole map. */
const CITY=CleanHouse.CITY;
let cityDrone=null,cityShield=null,cityDecor=null,cityTransition=null,cityShieldHit=0;
const cityBanner=document.createElement('aside');cityBanner.id='city-banner';cityBanner.hidden=true;cityBanner.setAttribute('role','status');document.body.appendChild(cityBanner);
const warpShortcut=document.createElement('button');warpShortcut.id='city-warp-shortcut';warpShortcut.textContent='◎ 워프';warpShortcut.hidden=true;warpShortcut.onclick=()=>showBaseBuilding('warp');document.body.appendChild(warpShortcut);
function cityTheme(){return CITY.THEMES[game.variant==='tycoon'?game.cityState().stage:0];}
function createCivicBuilding(g,d){let s=game.baseOps().buildings[d.id];box(g,0x152b44,0,.3,0,5,.5,4.5);ring(g,d.color,0,0,2.7,.1,.58);if(!s.built){for(let x of [-1.8,1.8])box(g,d.color,x,1.4,0,.14,2.4,.14);box(g,0x142c45,0,2.3,0,4,1.1,.3);let t=textPlane(d.icon,1.35,'#ffdf76');t.rotation.x=0;t.position.set(0,2.4,.2);g.add(t);return;}
 if(d.id==='reactor'){for(let x of [-1.2,1.2]){cyl(g,0x244853,x,1.5,0,.7,2.1);cyl(g,d.color,x,2.7,0,.65,.4);sphere(g,0xd4ff93,x,2.9,0,.35);}box(g,0x142b44,0,.7,0,4.3,.6,3);let rotor=group(g,0,3.25,0);for(let i=0;i<3;i++){let m=box(rotor,0xd8fc76,0,0,0,3,.1,.25);m.rotation.y=i*Math.PI/3;}g.userData.rotor=rotor;}
 else if(d.id==='repairbay'){box(g,d.color,0,1.2,0,3.9,1.8,3);box(g,0xf8edc7,0,2.2,0,4.3,.2,3.2);let arm=group(g,1.2,2.5,0);box(arm,0x233a50,0,.6,0,.3,1.2,.3);box(arm,0xffd451,-.7,1.15,0,1.6,.3,.35);sphere(g,0xeedbbc,-1.4,1.1,0,.3);g.userData.arm=arm;}
 else if(d.id==='shield'){for(let x of [-1.2,1.2]){box(g,0x234564,x,1.8,0,.7,3,.9);sphere(g,0x64deff,x,3.5,0,.44);}let orb=sphere(g,0x52dfff,0,2.1,0,.95);ring(g,0x2189fc,0,0,1.65,.11,2.1);g.userData.orb=orb;}
 else if(d.id==='drone'){box(g,d.color,0,.9,0,4.3,1,3.5);box(g,0x14243d,0,1.5,0,3.7,.18,3);let h=textPlane('H',1.3,'#8beeff');h.position.set(0,1.6,0);g.add(h);for(let x of [-1.8,1.8])sphere(g,0xffe775,x,1.8,-1.2,.17);}
 else if(d.id==='cafe'){box(g,0x5d3742,0,1.2,0,3.5,1.8,2.5);for(let i=0;i<5;i++)box(g,i%2?0xffecd3:d.color,(i-2)*.8,2.35,.55,.8,.25,3.3);let cup=cyl(g,0xffffff,0,3,0,.55,.9);ring(g,0x6f3425,0,0,.46,.09,3.47);for(let x of [-2.1,2.1]){cyl(g,0xe4b780,x,.7,2.4,.55,.16);cyl(g,0x243d55,x,.4,2.4,.1,.6);}}
 else if(d.id==='exchange'){box(g,0x4c385a,0,1.3,0,3.5,2,2.8);let roof=mesh('cone',d.color,g,0,2.9,0,2.8,1.4,2.4);for(let x of [-1.2,1.2]){box(g,x<0?0x2ed071:0xffd141,x,.7,2,.8,.8,.8);}let mark=textPlane('⇄',1.3,'#ffffff');mark.rotation.x=0;mark.position.set(0,1.4,1.45);g.add(mark);}
 else if(d.id==='warp'){for(let x of [-1.4,1.4]){box(g,0x1d294c,x,2,0,.7,3.5,1);box(g,0xb38aff,x,2,.6,.18,2.7,.12);}box(g,0xa178fa,0,3.7,0,3.5,.6,1);let mark=textPlane('◎',1.6,'#b9ffff');mark.rotation.x=0;mark.position.set(0,2.3,0);g.add(mark);ring(g,0xa584fc,0,0,1.1,.12,.62);}
 else if(d.id==='lab'){box(g,0x243853,0,1.05,0,3.8,1.5,3.2);for(let x of [-1.1,0,1.1]){cyl(g,x===0?0x49e8d4:0xe8c457,x,2.2,0,.35,1.5);sphere(g,0xdafaff,x,3,0,.43);}box(g,0xffdb69,0,.65,1.7,2.9,.4,.12);}
 let symbol=textPlane(d.icon,.9,'#ffffff');symbol.rotation.x=0;symbol.position.set(0,1.25,1.8);g.add(symbol);
}
function cityFloor(w,h,y,repeat){let t=cityTheme(),stage=game.cityState().stage,c=document.createElement('canvas');c.width=c.height=256;let x=c.getContext('2d');x.fillStyle=t.tile;x.fillRect(0,0,256,256);x.strokeStyle=t.line;x.lineWidth=3;x.strokeRect(2,2,252,252);if(stage===0){x.globalAlpha=.35;x.beginPath();x.moveTo(0,128);x.lineTo(256,128);x.moveTo(128,0);x.lineTo(128,256);x.stroke();}if(stage===1){x.beginPath();x.moveTo(128,16);x.lineTo(240,128);x.lineTo(128,240);x.lineTo(16,128);x.closePath();x.stroke();}if(stage===2){x.fillStyle='#a1bd77';for(let [a,b]of [[12,12],[244,12],[12,244],[244,244]]){x.beginPath();x.arc(a,b,8,0,TAU);x.fill();}x.strokeStyle='#cadca4';x.lineWidth=6;x.strokeRect(22,22,212,212);}if(stage===3){x.strokeStyle='#5f95b2';x.lineWidth=6;for(let n of [30,226]){x.beginPath();x.moveTo(0,n);x.lineTo(256,n);x.stroke();}x.fillStyle='#d4f5ff';for(let a of [30,226])for(let b of [30,226])x.fillRect(a-5,b-5,10,10);}if(stage===4){x.strokeStyle='#d9b668';x.lineWidth=4;x.beginPath();x.moveTo(128,12);x.lineTo(244,128);x.lineTo(128,244);x.lineTo(12,128);x.closePath();x.stroke();x.fillStyle='#fff1b7';for(let a of [0,256])for(let b of [0,256]){x.beginPath();x.arc(a,b,9,0,TAU);x.fill();}}let texture=new THREE.CanvasTexture(c);texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.repeat.set(repeat,repeat*h/w);let m=new THREE.Mesh(new THREE.PlaneGeometry(w,h),new THREE.MeshLambertMaterial({map:texture}));m.rotation.x=-Math.PI/2;m.position.y=y;m.receiveShadow=true;m.userData.customTexture=texture;environment.add(m);return m;}
function buildCityDecor(){let c=game.cityState(),theme=cityTheme();cityFloor(183,183,-.135,30);cityFloor(61,49,.195,12);cityDecor=group(environment);cityDecor.userData.dynamic=true;if(c.stage>0)for(let [x,z]of [[-30,-25],[30,-25],[-30,30],[30,30],[-75,18],[75,18],[-18,-75],[-18,75]]){let g=group(cityDecor,x,0,z);if(c.stage===1){box(g,0x174e5c,0,1.3,0,.45,2.6,.45);sphere(g,theme.accent,0,2.75,0,.45);}if(c.stage===2){cyl(g,0x8e714d,0,.6,0,1.4,1.1);sphere(g,0x428c55,0,1.55,0,1.4,.6,1.4);for(let i=0;i<5;i++)sphere(g,i%2?0xff7db1:0xffde69,Math.cos(i)*.8,1.9,Math.sin(i)*.8,.3);}if(c.stage===3){box(g,0x233c59,0,2.1,0,1.2,4.2,1.2);box(g,theme.accent,0,4.35,0,1.5,.25,1.5);box(g,0x92d8e2,0,2.6,.65,.25,2.4,.08);}if(c.stage===4){cyl(g,0x42365d,0,2,0,.6,4);mesh('cone',0xffd55c,g,0,4.5,0,1.2,1.3,1.2);let star=box(g,0xffefad,0,5.5,0,.55,.55,.55);star.rotation.z=Math.PI/4;}}batchFrontierScenery(cityDecor);
 cityDrone=group(actors);cyl(cityDrone,0x16405b,0,0,0,.5,.3);sphere(cityDrone,0x49dce8,0,.18,0,.35);for(let x of [-.7,.7])for(let z of [-.6,.6]){cyl(cityDrone,0x21304c,x,0,z,.34,.08);box(cityDrone,0xe0ffff,x,.07,z,.8,.025,.1);}let cargo=box(cityDrone,0xa675e0,0,-.4,0,.55,.45,.55);cityDrone.userData.cargo=cargo;
 cityShield=new THREE.Mesh(new THREE.SphereGeometry(4.15,24,12),new THREE.MeshBasicMaterial({color:0x54caff,transparent:true,opacity:.07,wireframe:true,depthWrite:false}));cityShield.position.set(0,2.2,2);environment.add(cityShield);
}
function clearCityTransition(){if(cityTransition){cityTransition.ring.removeFromParent();cityTransition.ring.geometry.dispose();cityTransition.ring.material.dispose();cityTransition=null;}cityBanner.hidden=true;}
const cityClear=clearFactoryViews;clearFactoryViews=function(){clearCityTransition();if(cityDrone){cityDrone.removeFromParent();disposeGroup(cityDrone);}cityDrone=null;cityShield=null;cityDecor=null;cityClear();};
const cityBuild=buildFactoryEnvironment;buildFactoryEnvironment=function(){cityBuild();buildCityDecor();};
const costLabel=cost=>Object.entries(cost).map(([k,n])=>({money:'¤ 돈',material:'▣ 재생 원료',cores:'◆ 정화 결정',raw:'자루',crop:'채소',toy:'장난감',cloth:'옷'})[k]+' '+n).join(' · ');
function facilityStatus(id){let c=game.cityState(),s=c.states[id];if(!game.baseOps().buildings[id].built)return '건설 전';if(!s.enabled)return '정지';if(id==='reactor'||id==='cafe')return s.run>0?Math.ceil(s.run)+'초 가동 중':'연료 대기';if(id==='shield')return '보호막 '+Math.ceil(c.shield)+' / '+(120+(game.buildingLevel('shield')-1)*40);if(id==='repairbay')return '수리 '+Math.floor(c.repairs)+' HP';if(id==='drone')return (c.drone.load?'복귀 중 · '+c.drone.load.n+'개':'회수 '+c.droneDelivered+'개')+' · 연료 '+Math.ceil(s.run)+'초';if(id==='warp')return c.warpCool>0?Math.ceil(c.warpCool)+'초 준비':'이동 준비';if(id==='exchange')return c.tradeCool>0?Math.ceil(c.tradeCool)+'초 준비':'교환 가능';return '연구 '+Object.values(c.research).reduce((a,b)=>a+b,0)+' / 9';}
const baseBuilding=showBaseBuilding;showBaseBuilding=function(id){let d=CITY.FACILITIES.find(d=>d.id===id);if(!d)return baseBuilding(id);let s=game.baseOps().buildings[id],c=game.cityState(),req=game.facilityRequirements(id);let controls='';if(s.built&&id==='lab')controls='<div class="city-actions">'+[['production','생산 속도'],['logistics','화물 이동 속도'],['defense','자동 방어 공격력']].map(([k,n])=>'<button data-research="'+k+'" '+(c.research[k]>=3?'disabled':'')+'><b>'+n+' +'+c.research[k]*10+'%</b><small>'+(c.research[k]>=3?'연구 완료':'+10% 연구 · '+costLabel(game.researchCost(k)))+'</small></button>').join('')+'</div>';
 if(s.built&&id==='exchange')controls='<div class="city-actions">'+CITY.TRADES.map(t=>'<button data-trade="'+t.id+'" '+(c.tradeCool>0?'disabled':'')+'><b>'+t.name+'</b><small>'+costLabel(t.cost)+' → '+costLabel(t.reward)+'</small></button>').join('')+'</div>';
 if(s.built&&id==='warp')controls='<p>터미널 또는 외곽 운송 거점 가까이에서 사용할 수 있어요.</p><div class="city-actions">'+[{id:-1,name:'중앙 터미널'},...CleanHouse.FRONTIER.regions].map(r=>'<button data-warp="'+r.id+'" '+(!game.canCityWarp()||c.warpCool>0?'disabled':'')+'>'+r.name+' · ¤12</button>').join('')+'</div>';
 if(s.built&&id==='drone')controls='<p>수거 구역 선택 · 바닥에 떨어진 자원을 회수합니다.</p><div class="city-patrol">'+['중앙',...CleanHouse.FRONTIER.regions.map(r=>r.name)].map((n,i)=>'<button data-patrol="'+i+'" aria-pressed="'+(c.drone.patrol===i)+'">'+n+'</button>').join('')+'</div>';
 showModal('civic','<button class="close" id="city-close" aria-label="닫기">×</button><div class="eyebrow">'+d.category+' · '+CITY.THEMES[d.stage].name+'</div><h2>'+d.icon+' '+d.name+'</h2><p>'+d.benefit+'</p><div class="ops-benefit">'+facilityStatus(id)+'</div>'+(s.built?controls+btn('city-toggle',c.states[id].enabled?'가동 중 · 일시 정지':'가동 재개','secondary'):'<div class="ops-cost">남은 비용<br><b>'+opsCosts(d)+'</b></div><ul class="ops-conditions">'+req.map(q=>'<li class="'+(q.ok?'met':'')+'">'+(q.ok?'✓':'○')+' '+q.label+'</li>').join('')+'</ul>'+btn('city-fund','남은 비용으로 건설'))+btn('city-location','건물 자리로 안내','secondary')+btn('city-catalog','도시 성장 · 새 시설','secondary'));
 $('city-close').onclick=closeModal;$('city-location').onclick=()=>{game.waypoint={x:d.x,z:d.z};closeModal();};$('city-catalog').onclick=showCityCatalog;if($('city-fund'))$('city-fund').onclick=()=>{if(game.fundBaseBuilding(id,Infinity)){processEvents();save();showBaseBuilding(id);}else toast(req.every(q=>q.ok)?'돈·원료·결정을 모아주세요':'먼저 표시된 성장 조건을 달성하세요');};if($('city-toggle'))$('city-toggle').onclick=()=>{game.toggleFacility(id);save();showBaseBuilding(id);};document.querySelectorAll('[data-research]').forEach(b=>b.onclick=()=>{if(game.startResearch(b.dataset.research)){processEvents();save();showBaseBuilding(id);}else toast('가동 상태와 연구 비용을 확인하세요');});document.querySelectorAll('[data-trade]').forEach(b=>b.onclick=()=>{if(game.cityTrade(b.dataset.trade)){processEvents();save();showBaseBuilding(id);}else toast('가동 상태·남은 시간·교환 자원을 확인하세요');});document.querySelectorAll('[data-warp]').forEach(b=>b.onclick=()=>{if(game.cityWarp(+b.dataset.warp)){closeModal();processEvents();save();}else toast('이동 위치·가동 상태·돈을 확인하세요');});document.querySelectorAll('[data-patrol]').forEach(b=>b.onclick=()=>{game.setDronePatrol(+b.dataset.patrol);save();showBaseBuilding(id);});
};
function cityMilestoneCard(stage){let c=game.cityState(),earned=stage<=c.stage,goals=game.milestoneGoals(stage);return '<article class="city-stage '+(earned?'earned':'')+'"><b>'+(['Ⅰ','Ⅱ','Ⅲ','Ⅳ'][stage-1])+' '+CITY.THEMES[stage].name+(earned?' ✓':'')+'</b><small>'+['','청록 다이아 타일 · 안내 조명','정원 타일 · 꽃 화단','산업 패널 · 신호 기둥','별빛 타일 · 금색 첨탑'][stage]+'</small><ul>'+goals.map(q=>'<li class="'+(earned||q.ok?'met':'')+'"><span>'+(earned||q.ok?'✓':'○')+' '+q.label+'</span><b>'+Math.min(q.value,q.goal)+' / '+q.goal+'</b></li>').join('')+'</ul><div class="city-stage-fill"><i style="width:'+(earned?100:goals.reduce((n,q)=>n+Math.min(1,q.value/q.goal),0)/goals.length*100)+'%"></i></div><small>달성 보상 ¤ '+[0,80,180,350,600][stage]+' · ◆ '+[0,2,4,6,10][stage]+'</small></article>';}
function showCityCatalog(){let c=game.cityState();showModal('citycatalog','<button class="close" id="city-close" aria-label="닫기">×</button><div class="eyebrow">CITY GROWTH · '+c.stage+' / 4</div><h2>'+CITY.THEMES[c.stage].name+'</h2><p>목표를 모두 채우면 마을 전체가 새 모습으로 바뀝니다.<br>달성한 배경과 보상은 저장됩니다.</p><div class="city-milestones">'+(c.stage<4?cityMilestoneCard(c.stage+1):'<div class="ops-benefit">★ 별빛 수도 완성<br>연구·생산·무한 방어는 계속됩니다.</div>')+'</div><details class="city-all"><summary>전체 성장 단계 보기</summary>'+[1,2,3,4].filter(n=>n!==c.stage+1).map(cityMilestoneCard).join('')+'</details><h3>새 운영 시설 · 8종</h3><div class="city-catalog">'+CITY.FACILITIES.map(d=>{let built=game.baseOps().buildings[d.id].built,unlocked=game.facilityRequirements(d.id).every(q=>q.ok);return '<button data-city="'+d.id+'" style="--facility:#'+d.color.toString(16)+'"><b>'+d.icon+' '+d.name+'</b><em>'+d.category+' · '+(built?facilityStatus(d.id):unlocked?'건설 가능':CITY.THEMES[d.stage].name+' 해금')+'</em><small>'+d.benefit+'</small><strong>'+(built?'✓ 건설 완료':opsCosts(d))+'</strong></button>';}).join('')+'</div>'+btn('city-network','구역 레일 · 지점 건설','secondary'),true);$('city-close').onclick=closeModal;$('city-network').onclick=showBaseNetwork;document.querySelectorAll('[data-city]').forEach(b=>b.onclick=()=>showBaseBuilding(b.dataset.city));}
const networkCity=showBaseNetwork;showBaseNetwork=function(){networkCity();let b=document.createElement('button');b.className='btn city-open';b.id='city-open';let c=game.cityState(),goals=game.milestoneGoals();b.innerHTML='✦ '+CITY.THEMES[c.stage].name+' · 성장 '+c.stage+'/4<br><small>새 시설 8종 · 다음 목표 '+goals.filter(q=>q.ok).length+'/'+goals.length+'</small>';b.onclick=showCityCatalog;document.querySelector('.ops-lines').before(b);for(let d of CITY.FACILITIES)document.querySelector('[data-base="'+d.id+'"]')?.remove();};
const cityQuick=showQuickMenu;showQuickMenu=function(){cityQuick();if(game.variant==='tycoon'&&modalKind==='menu'){let b=document.createElement('button');b.id='city-menu';b.textContent='✦ 도시 성장 · 새 시설';b.onclick=showCityCatalog;document.querySelector('.quick-grid')?.prepend(b);}};
const benefitBase=showUpgradeInfo;showUpgradeInfo=function(id){benefitBase(id);let c=game.cityState(),p=document.createElement('p');p.className='smallnote';p.textContent='추가 운영 보너스: 생산 ×'+game.civicProductionRate().toFixed(2)+' · 화물 속도 ×'+game.civicRailRate().toFixed(2)+' · 자동 방어 ×'+game.civicDefenseRate().toFixed(2)+'. 위 레벨 비교는 보너스 적용 전 기본 수치입니다.';document.querySelector('.ops-benefit')?.after(p);};
function startCityTransition(e){let old=CITY.THEMES[Math.max(0,e.stage-1)];clearCityTransition();buildEnvironment();let ring=new THREE.Mesh(new THREE.RingGeometry(.98,1.04,80),new THREE.MeshBasicMaterial({color:CITY.THEMES[e.stage].accent,transparent:true,opacity:.8,side:THREE.DoubleSide,depthWrite:false}));ring.rotation.x=-Math.PI/2;ring.position.set(0,.7,2);effects.add(ring);cityTransition={age:0,ring,oldSky:new THREE.Color(old.sky),newSky:new THREE.Color(CITY.THEMES[e.stage].sky)};cityBanner.innerHTML='<span>마일스톤 달성 · '+e.stage+' / 4</span><strong>'+e.name+'</strong><small>새 바닥 · 새 풍경　¤ +'+e.money+'　◆ +'+e.cores+'</small>';cityBanner.hidden=false;cityBanner.classList.remove('arrive');void cityBanner.offsetWidth;cityBanner.classList.add('arrive');save();tone(780,.25);}
const cityEvents=handleExpansionEvent;handleExpansionEvent=function(e){cityEvents(e);if(e.type==='city_milestone')startCityTransition(e);if(e.type==='civic_research')benefitNotice(({production:'생산',logistics:'물류',defense:'자동 방어'})[e.key]+' 연구 Lv.'+e.level,['영구 효과 +'+e.level*10+'%']);if(e.type==='civic_trade')benefitNotice('⇄ '+e.name,['교환 완료 · '+game.cityState().tradeCool+'초 뒤 다음 거래']);if(e.type==='civic_repair'){spawnVividFX('touch',{x:0,z:2});if(Math.hypot(game.player.x,game.player.z-2)<20)floatReward('+'+e.n,0,2,'material');}if(e.type==='shield_hit')cityShieldHit=.25;if(e.type==='civic_warp'){spawnVividFX('bubble',e);spawnVividFX('bubble',{x:e.tx,z:e.tz});toast('등짐과 함께 이동했어요');}if(e.type==='drone_delivery')floatReward('+'+e.n,e.x,e.z,'material');};
const cityRender=renderExpansion;renderExpansion=function(dt){cityRender(dt);if(game.variant!=='tycoon'){warpShortcut.hidden=true;cityBanner.hidden=true;return;}let c=game.cityState(),o=game.baseOps();for(let v of opsLabels){if(!v.d.civic)continue;let built=o.buildings[v.d.id].built,unlocked=game.facilityRequirements(v.d.id).every(q=>q.ok);v.el.innerHTML='<b>'+v.d.icon+' '+v.d.name+' <em>!</em></b><small>'+(built?facilityStatus(v.d.id):unlocked?opsCosts(v.d):'⚿ '+CITY.THEMES[v.d.stage].name)+'</small>';if(v.g.userData.rotor&&game.civicActive(v.d.id))v.g.userData.rotor.rotation.y+=dt*3;if(v.g.userData.arm)v.g.userData.arm.rotation.z=Math.sin(visTime*1.5)*.15;if(v.g.userData.orb)v.g.userData.orb.scale.setScalar(.85+Math.sin(visTime*2)*.08);}
 if(cityDrone){cityDrone.visible=o.buildings.drone.built;cityDrone.position.set(c.drone.x,3.3+Math.sin(visTime*6)*.08,c.drone.z);cityDrone.rotation.y=visTime*.3;cityDrone.userData.cargo.visible=!!c.drone.load;}if(cityShield){cityShieldHit=Math.max(0,cityShieldHit-dt);cityShield.visible=game.civicActive('shield')&&c.shield>0;cityShield.material.opacity=cityShieldHit>0?.32:.06+c.shield/120*.045;cityShield.rotation.y=visTime*.1;}
 warpShortcut.hidden=!running||!game.civicActive('warp')||!game.canCityWarp();if(!warpShortcut.hidden)warpShortcut.textContent=c.warpCool>0?'◎ '+Math.ceil(c.warpCool)+'s':'◎ 워프 · ¤12';let small=frontierMapButton.querySelector('small'),goals=game.milestoneGoals();if(small&&!game.factory.frontier.contract&&game.factory.frontier.surgeTime<=0)small.textContent='✦ '+CITY.THEMES[c.stage].name+' · '+(c.stage===4?'완성':goals.filter(q=>q.ok).length+'/'+goals.length);
 if(cityTransition){let t=cityTransition; t.age+=dt;let ratio=Math.min(1,t.age/3);scene.background.copy(t.oldSky).lerp(t.newSky,ratio);scene.fog.color.copy(scene.background);t.ring.visible=!reducedMotion;t.ring.scale.setScalar(1+t.age*36);t.ring.material.opacity=Math.max(0,.8-t.age*.23);if(t.age>5)clearCityTransition();}
};

