const KIT=CleanHouse.PLAYER_GEAR;
const tallNexus=createBaseNexus;createBaseNexus=function(parent){tallNexus(parent);opsNexus.g.scale.set(1.15,2.25,1.15);opsNexus.g.traverse(m=>{if(m.isMesh){m.userData.nexusFadeMaterial=m.material.clone();m.material=m.userData.nexusFadeMaterial;}});};
const kitModal=showModal;showModal=function(kind,html,wide=false){kitModal(kind,html,wide);if(!document.body.classList.contains('notplaying')&&!['title','modes'].includes(kind)&&!$('modal').querySelector('.close')){let b=document.createElement('button');b.className='close';b.textContent='×';b.setAttribute('aria-label','메뉴 접기');b.onclick=closeModal;$('modal').prepend(b);}};
addEventListener('keydown',e=>{if(e.code==='Escape'&&!running&&!document.body.classList.contains('notplaying')&&!['title','modes'].includes(modalKind))closeModal();});
function kitStats(){return '이동 '+((5.8+game.levels.speed*.35)*game.gearSpeed()).toFixed(1)+' · 현장 투입 ×'+game.buildRate().toFixed(1)+' · 청소 범위 '+game.range.toFixed(1)+' · 공격 ×'+game.characterAttack().toFixed(2);}
function showEquipment(){let k=game.kit();showModal('equipment','<button class="close" id="kit-close">×</button><div class="eyebrow">¤ '+game.money+' · 장착하면 즉시 적용</div><h2>나의 작업 장비</h2><div class="ops-benefit">'+kitStats()+'</div><div class="kit-list">'+KIT.map(d=>'<article style="--kit:#'+d.color.toString(16)+'"><b>'+d.icon+' '+d.name+' · Lv.'+k.ranks[d.id]+'</b><p>'+d.desc+'</p><button data-buy-gear="'+d.id+'" '+(k.ranks[d.id]>=3?'disabled':'')+'>'+(k.ranks[d.id]>=3?'최대 강화':(k.ranks[d.id]?'강화':'구매 · 장착')+' ¤ '+game.gearCost(d.id))+'</button>'+(k.ranks[d.id]?'<button data-equip="'+d.id+'" aria-pressed="'+k.equipped[d.id]+'">'+(k.equipped[d.id]?'장착 중 · 해제':'장착하기')+'</button>':'')+'</article>').join('')+'</div><p class="smallnote">장갑은 비용 할인이 아니라 현장 투입량을 늘립니다. 스쿠터는 걷는 이동에 적용됩니다. 먼지 유도는 주변 빈자리만 사용해 실제 수량이 줄 수 있습니다.</p>'+btn('kit-summon',k.summonCool>0?'유도기 준비 '+Math.ceil(k.summonCool)+'초':'✧ 주변 자원 유도 · ¤5','secondary'),true);$('kit-close').onclick=closeModal;document.querySelectorAll('[data-buy-gear]').forEach(b=>b.onclick=()=>{if(!game.buyGear(b.dataset.buyGear))toast('돈 또는 최대 레벨을 확인하세요');processEvents();save();showEquipment();});document.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{game.toggleGear(b.dataset.equip);save();showEquipment();});$('kit-summon').onclick=()=>{if(game.summonResources()){closeModal();processEvents();save();}else toast('유도기를 장착하고 돈 5와 빈자리, 재사용 시간을 확인하세요');};}
const kitQuick=showQuickMenu;showQuickMenu=function(){kitQuick();let grid=document.querySelector('.quick-grid');if(!grid)return;if(game.variant==='tycoon'){let b=document.createElement('button');b.id='kit-open';b.textContent='♟ 장비 상점 · 탈것';b.onclick=showEquipment;grid.prepend(b);}let b=document.createElement('button');b.textContent='◉ 화면 패널 숨김 · 복원';b.onclick=showPanelSettings;grid.append(b);};
const kitBase=showBaseBuilding;showBaseBuilding=function(id){kitBase(id);let s=game.baseOps().buildings[id];if(!s?.built)return;let block=document.createElement('section');block.className='kit-upgrade';block.innerHTML='<h3>시설 Lv.'+s.level+' / 3</h3><p>'+game.baseBenefit(id)+'</p>'+(s.level<3?'<p>다음: '+game.baseBenefit(id,s.level+1)+'</p><button id="kit-base-up">강화 · '+costLabel(game.baseUpgradeCost(id))+'</button>':'<b>최대 강화 완료</b>');$('modal').querySelector('h2').after(block);if($('kit-base-up'))$('kit-base-up').onclick=()=>{if(!game.upgradeBaseBuilding(id))toast('돈·원료·결정을 확인하세요');processEvents();save();showBaseBuilding(id);};if(id==='warp'){let fare=12-(s.level-1)*2;document.querySelectorAll('[data-warp]').forEach(b=>b.textContent=b.textContent.replace('¤12','¤'+fare));}if(id==='shield'){let e=document.querySelector('.ops-benefit');if(e)e.textContent='보호막 '+Math.ceil(game.cityState().shield)+' / '+(120+(s.level-1)*40);}let benefit=block.nextElementSibling;if(benefit?.tagName==='P'&&s.level>1)benefit.textContent=game.baseBenefit(id)+' · 연료/재료는 기존과 동일';};
function routeDiagram(selected){return '<svg class="kit-routes" viewBox="-65 -68 135 133" role="img" aria-label="중앙과 동서남북 구역 연결 노선도">'+OPS.LINES.map(l=>'<polyline points="'+l.points.map(p=>p.join(',')).join(' ')+'" fill="none" stroke="#'+l.color.toString(16)+'" stroke-width="'+(l.id===selected?3:1.7)+'" opacity="'+(game.lineActive(l.id)?1:.3)+'" '+(game.lineActive(l.id)?'':'stroke-dasharray="3 2"')+'/>').join('')+OPS.LINES.map(l=>{let p=l.id==='hub'?[-10,7]:l.points.at(-1);return '<circle cx="'+p[0]+'" cy="'+p[1]+'" r="2.5" fill="#fff"/><text x="'+p[0]+'" y="'+(p[1]-5)+'" text-anchor="middle" fill="white" font-size="5">'+({hub:'중앙',north:'결정 광장',east:'장난감',south:'정원',west:'의류'})[l.id]+'</text>';}).join('')+'<circle cx="'+game.player.x+'" cy="'+game.player.z+'" r="2" fill="#ffef69"/></svg>';}
function showRailTravel(selected='hub'){let near=game.railDistance().distance<4,lv=game.factory.sites.rail.level;showModal('railtravel','<button class="close" id="travel-close">×</button><h2>카트 목적지 선택</h2>'+routeDiagram(selected)+'<p>실선은 연결됨 · 점선은 미연결/정지 · 노란 점은 나</p><div class="ops-benefit">레일 Lv.'+lv+' · 카트 속도 '+game.passengerSpeed().toFixed(1)+'<br>원료 집하장 → 구역 공장/지점 → 중앙 판매대<br>금색 수금선: 판매대/지역 지점 → 중앙 금고</div><div class="kit-destinations">'+OPS.LINES.map(l=>'<button data-travel="'+l.id+'" '+(!near||!game.lineActive(l.id)?'disabled':'')+'>'+l.name+'<small>'+(!game.lineActive(l.id)?'연결 필요':near?'이곳으로 출발':'선로 4 이내에서 탑승')+'</small></button>').join('')+'</div>'+btn('travel-upgrade','레일 강화 · 운송량/속도 확인','secondary')+btn('travel-network','레일 설치 · 노선 관리','secondary'));$('travel-close').onclick=closeModal;$('travel-network').onclick=showBaseNetwork;$('travel-upgrade').onclick=()=>game.factory.sites.rail.built?showUpgradeInfo('rail'):showBaseNetwork();document.querySelectorAll('[data-travel]').forEach(b=>b.onclick=()=>{if(game.boardPassenger(b.dataset.travel)){closeModal();processEvents();save();}else toast('연결된 선로 가까이 이동하세요');});}
const kitNetwork=showBaseNetwork;showBaseNetwork=function(){kitNetwork();let wrap=document.createElement('section');wrap.innerHTML=routeDiagram('hub')+'<button class="btn secondary" id="travel-open">카트 목적지 · 전체 노선 보기</button>';$('city-open').after(wrap);$('travel-open').onclick=()=>showRailTravel();};
const routeInfo=showUpgradeInfo;showUpgradeInfo=function(id){routeInfo(id);if(id==='rail'){let p=document.createElement('p');p.textContent='모든 연결 지선에 공통 적용 · 카트 '+game.passengerSpeed().toFixed(1)+' → '+(game.passengerSpeed()+2).toFixed(1)+' · 자루 급송 '+(80+(game.factory.sites.rail.level-1)*30)+'개/회';$('modal').querySelector('.ops-benefit').after(p);}};
const transitBar=document.createElement('div');transitBar.id='transit-bar';transitBar.hidden=true;document.body.appendChild(transitBar);
const HUD_GROUPS=[{id:'radar',name:'레이더',selectors:['#base-radar']},{id:'quest',name:'목표·진행 안내',selectors:['#quest-peek','#vivid-status','#activity-meter']},{id:'stats',name:'돈·체력·습격',selectors:['.statusgroup','#corehud','#compact-vitals','#raidclock','.chaptermini','.bossbar','.saving','#story-health']},{id:'cargo',name:'등짐·콤보',selectors:['#cargodock','#stackbadge','#combohud']},{id:'map',name:'지도·워프 버튼',selectors:['#frontier-map-button','#city-warp-shortcut','.minimap']},{id:'labels',name:'월드 이름·발판 안내',selectors:['#labels']},{id:'controls',name:'행동·이동 안내',selectors:['.bottomdock','#interactpanel','#mobilehint','.hint','#transit-bar','#summon-shortcut']},{id:'notices',name:'보상·완료 알림',selectors:['#ops-notice','#city-banner','#celebration','#toast']}];
let panelPrefs={};try{panelPrefs=JSON.parse(localStorage.getItem('clean-keep-panels-v13')||'{}');}catch{}if(!panelPrefs||typeof panelPrefs!=='object')panelPrefs={};
const panelStyle=document.createElement('style');document.head.appendChild(panelStyle);const panelEye=document.createElement('button');panelEye.id='panel-eye';panelEye.textContent='◉';panelEye.setAttribute('aria-label','화면 숨김 및 복원');panelEye.onclick=showPanelSettings;document.body.appendChild(panelEye);
