function showPanelSettings(){showModal('panels','<button class="close" id="panels-close">×</button><h2>화면을 가볍게</h2><p>숨겨도 게임은 계속됩니다. 작은 ◉ 버튼으로 다시 켤 수 있어요.</p><div class="kit-destinations">'+HUD_GROUPS.map(g=>'<button data-panel="'+g.id+'" aria-pressed="'+!panelPrefs[g.id]+'">'+g.name+' · '+(panelPrefs[g.id]?'숨김':'표시')+'</button>').join('')+'</div>'+btn('panels-all',panelPrefs.all?'전체 다시 표시':'전체 패널 숨기기','secondary'));$('panels-close').onclick=closeModal;document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>{panelPrefs.all=false;panelPrefs[b.dataset.panel]=!panelPrefs[b.dataset.panel];applyPanels();showPanelSettings();});$('panels-all').onclick=()=>{if(panelPrefs.all)panelPrefs={};else panelPrefs.all=true;applyPanels();closeModal();};}applyPanels();
