 if(game.variant==='journey'){for(let v of lampViews){v.label.style.pointerEvents='auto';v.label.onclick=()=>showLampInfo(v.i);let m=stationVisuals.get('built-story-lamp-'+v.i);if(m){let lv=game.ensureStoryGuard().levels[v.i];m.userData.turret.scale.setScalar(1+(lv-1)*.08);}}transitBar.hidden=true;return;}if(game.variant!=='tycoon'){transitBar.hidden=true;return;}if(opsNexus){let behind=Math.hypot(game.player.x,game.player.z-2)<9&&game.player.x+game.player.z-2<0;opsNexus.g.traverse(m=>{let mat=m.userData.nexusFadeMaterial;if(!mat)return;if(m.material!==mat){mat.color.copy(m.material.color);m.material=mat;}let alpha=behind?.28:1;if(mat.opacity!==alpha){mat.opacity=alpha;mat.transparent=behind;mat.depthWrite=!behind;mat.needsUpdate=true;}});}if(cityShield){cityShield.scale.set(1.2,1.9,1.2);cityShield.position.y=7.5;}let label=factoryLabels.find(l=>l.kind==='nexus');if(label){placeTag(label.el,0,15.5,2);label.el.style.top=Math.max(106,parseFloat(label.el.style.top))+'px';}
 for(let v of opsLabels){let s=game.baseOps().buildings[v.d.id];if(s.built)v.el.querySelector('b')?.append(document.createTextNode(' · Lv.'+s.level));}if(!warpShortcut.hidden)warpShortcut.textContent=game.cityState().warpCool>0?'◎ '+Math.ceil(game.cityState().warpCool)+'s':'◎ 워프 · ¤'+(12-(game.buildingLevel('warp')-1)*2);
