for(let v of opsLabels){let s=game.baseOps().buildings[v.d.id];if(s.built){let text=v.d.icon+' '+v.d.name+' · '+s.level;if(v.el.textContent!==text)v.el.textContent=text;v.el.classList.add('flow-compact');}}
let ride=game.flow().ride||game.kit().ride,c=game.frontierContext(),pad=game.railPads().find(d=>!d.ready&&Math.hypot(p.x-d.x,p.z-d.z)<3),loop=FLOW.LOOPS.find(d=>d.id!=='town'&&!game.loopBuilt(d.id)&&Math.hypot(p.x-d.x,p.z-d.z)<3),near=Math.min(game.railDistance().distance,game.loopDistance().distance)<=4;let html='';
