if(game.factory.railRide||near){$('interactpanel').classList.remove('visible');}transitBar.hidden=!running||!html;if(transitBar.dataset.renderKey!==html){transitBar.dataset.renderKey=html;transitBar.innerHTML=html;transitBar.querySelectorAll('button').forEach(b=>b.onclick=()=>{let ok=b.dataset.flow==='ride'?game.boardLoop():b.dataset.flow==='leave'?game.leavePassenger():b.dataset.flow==='pad'?game.installFieldRail(b.dataset.id):b.dataset.flow==='loop'?game.installLoop(b.dataset.id):game.factoryAction();if(!ok)toast('필요한 돈·결정과 연결 조건을 확인하세요');processEvents();save();});}
