const flowRadar=drawRadar;drawRadar=function(canvas){flowRadar(canvas);let ctx=canvas.getContext('2d'),w=canvas.width;ctx.save();ctx.translate(w/2,w/2);ctx.scale(w/188,w/188);for(let l of FLOW.LOOPS)if(game.loopBuilt(l.id)){ctx.strokeStyle='#'+l.color.toString(16);ctx.lineWidth=1;ctx.beginPath();(game.loopPoints?game.loopPoints(l):l.points).forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.stroke();}for(let f of FLOW.FARMS){ctx.strokeStyle='#'+f.color.toString(16);ctx.lineWidth=1.4;ctx.strokeRect(f.x-9,f.z-8,18,16);}ctx.restore();};
const flowEvent=handleExpansionEvent;handleExpansionEvent=function(e){flowEvent(e);if(e.type==='cart_hit'){spawnVividFX('bubble',e);if(!reducedMotion)impact=Math.max(impact,.045);tone(220,.06);}if(e.type==='loop_board')spawnVividFX('build',e);};
const flowStyle=document.createElement('style');flowStyle.textContent='.flow-tag{position:absolute;transform:translate(-50%,-100%);padding:5px 9px;border:1px solid #67e8ff;border-radius:7px;background:#102b42ef;color:#fff;font:700 12px system-ui;white-space:nowrap;pointer-events:auto;box-shadow:0 3px 0 #071726}.flow-install{color:#7ae9ff;font-size:11px}.ops-world-tag.flow-compact{padding:6px 9px;font-size:12px;min-width:0}.flow-tag[hidden]{display:none}';document.head.appendChild(flowStyle);

