function showMaterialStore(){let s=game.progression(),f=game.factory,nearStore=Math.hypot(game.player.x-3.3,game.player.z-6)<=6,nearSale=Math.hypot(game.player.x+12,game.player.z-11)<=4;showModal('materialstore','<button class="close" id="material-close">×</button><h2>▣ 재생 원료</h2><p>초록 네모 블록입니다. <b>건물 재료로 쓰거나 손님에게 팔 수 있어요.</b></p><div class="resource-flow"><span>보라 먼지 자루</span><b>→ ♻ →</b><span>초록 재생 원료</span></div><div class="material-grid"><div>등에 운반 중<b>'+f.cargo.material+'</b></div><div>재활용기 보관<b>'+game.supplies+'</b></div><div class="reserved">건설 전용 보관<b>'+s.constructionStock+'</b></div><div>판매대 미판매 재고<b>'+f.lanes[0].stock+'</b></div></div><p class="smallnote">건설할 때 위의 운반·재활용기·건설 보관 원료를 자동 사용합니다. 직접 등에 싣지 않아도 돼요. 판매대 재고는 먼저 회수하세요. 손님이 이미 가져간 원료와 운송 중인 화물은 회수되지 않습니다.</p><button class="btn" id="material-reclaim">'+(nearSale?'판매대 남은 원료 전부 회수':'원료 판매대로 이동 → 회수')+'</button><button class="btn secondary" id="material-reserve">'+(nearStore?'원료 20개 건설 전용 보관':'재활용기로 이동 → 보관')+'</button><button class="btn secondary" id="material-release">'+(nearStore?'원료 전부 등에 싣기':'재활용기로 이동 → 꺼내기')+'</button><p class="smallnote">건설 전용 원료는 판매대·생산 레일로 자동 이동하지 않아요. 돈은 금색 동전, 정화 결정은 세균 처치 후 떨어지는 분홍 마름모입니다.</p>');$('material-close').onclick=closeModal;function perform(kind){let target=kind==='reclaim'?{x:-12,z:11}:{x:3.3,z:6},near=kind==='reclaim'?nearSale:nearStore;if(!near){game.waypoint=target;closeModal();return;}let ok=kind==='reclaim'?game.reclaimSaleMaterial(game.factory.lanes[0].stock):kind==='reserve'?game.storeConstructionMaterial():game.collectMaterial();if(!ok)toast('이곳에서 사용할 재생 원료가 없어요');processEvents();save();showMaterialStore();}for(let k of ['reclaim','reserve','release'])$('material-'+k).onclick=()=>perform(k);}
function workOrderHTML(){let plan=game.workPlan(),i=plan.findIndex(t=>!t.done),list=i<0?[]:plan.slice(i,i+5),a=PROGRESS.AREAS.find(a=>a.stage>game.openMapStage());return '<h3>이어서 할 일</h3><ol class="work-orders">'+list.map((t,j)=>'<li class="'+(j===0?'current':'')+'"><b>'+(t.done?'✓ ':j===0?'지금 · ':'다음 · ')+t.title+'</b></li>').join('')+'</ol>'+(a?'<details class="work-unlock"><summary>다음 구역: '+a.name+'</summary><p>승급 '+a.stage+' 달성 시 길이 열립니다.</p>'+game.milestoneGoals().map(q=>'<div>'+(q.ok?'✓':'○')+' '+q.label+' '+q.value+'/'+q.goal+'</div>').join('')+'</details>':'<small>네 구역 모두 개방 · 계속 운영할 수 있어요.</small>');}
function showWorkOrders(){showQuickMenu();}
const progressQuestMenu=installQuestMenu;installQuestMenu=function(){progressQuestMenu();if(game.variant!=='tycoon')return;let section=document.createElement('section');section.className='work-section';section.innerHTML=workOrderHTML()+'<button class="route-btn" id="work-materials">▣ 필요한 자원 · 보관함 확인</button>';document.querySelector('.quest-menu').append(section);$('work-materials').onclick=showMaterialStore;};
const progressQuick=showQuickMenu;showQuickMenu=function(){progressQuick();if(game.variant!=='tycoon')return;let grid=document.querySelector('.quick-grid');if(grid){let b=document.createElement('button');b.textContent='▣ 재생 원료 · 보관 / 회수';b.onclick=showMaterialStore;grid.prepend(b);}};
const progressGuide=renderQuestGuide;renderQuestGuide=function(){progressGuide();if(game.variant!=='tycoon'||questPeek.hidden)return;let q=game.questGuide(),plan=game.workPlan(),i=plan.findIndex(t=>!t.done),next=q.title===plan[i]?.title?plan[i+1]?.title:plan[i]?.title;questPeek.innerHTML='<span>지금 할 일 <b>'+q.progress+'</b></span><strong>'+q.title+'</strong>'+(next?'<small>다음 → '+next+'</small>':'');};
const materialShortcut=document.createElement('button');materialShortcut.id='material-shortcut';materialShortcut.textContent='▣ 재생 원료 · 보관/회수';materialShortcut.onclick=()=>takeLocalMaterial();materialShortcut.hidden=true;document.body.appendChild(materialShortcut);HUD_GROUPS.find(g=>g.id==='controls').selectors.push('#material-shortcut');applyPanels();
const progressRender=renderExpansion;renderExpansion=function(dt){progressRender(dt);materialShortcut.hidden=!running||game.variant!=='tycoon';if(game.variant!=='tycoon')return;let p=game.player,atSale=Math.hypot(p.x+12,p.z-11)<=4,amount=atSale?game.factory.lanes[0].stock:game.supplies+game.progression().constructionStock;materialShortcut.textContent=atSale?'↶ 남은 원료 회수 · '+amount:'▣ 원료 싣기 · '+amount;materialShortcut.disabled=amount===0||!!game.factory.railRide||!!game.factory.frontier?.express;materialShortcut.hidden=materialShortcut.hidden||Math.min(Math.hypot(p.x-3.3,p.z-6),Math.hypot(p.x+12,p.z-11)+2)>6;for(let v of gateViews){v.el.hidden=!running||Math.hypot(p.x-v.a.x,p.z-v.a.z)>24||game.openMapStage()>=v.a.stage;if(!v.el.hidden)placeTag(v.el,v.a.x,3,v.a.z);}if(constructionView){constructionView.el.hidden=!running||Math.hypot(p.x-5.8,p.z-6)>14;constructionView.el.textContent='▣ 원료 싣기 · '+(game.supplies+game.progression().constructionStock);placeTag(constructionView.el,5.8,2,6);}for(let v of [...flowTags,...opsLabels]){let d=v.d;if(d&&!game.mapPositionOpen(d.x,d.z))v.el.hidden=true;}};
const progressEvents=handleExpansionEvent;handleExpansionEvent=function(e){progressEvents(e);if(e.type==='map_unlock'){buildEnvironment();benefitNotice('길이 열렸어요 · '+e.name,['지금 할 일 목록을 이어가며 새 구역을 탐험하세요.']);}if(e.type==='construction_stock'){statKick('supplies');toast('재생 원료 '+e.n+'개 → 건설 전용 보관');}};
const progressRadar=drawRadar;drawRadar=function(canvas){progressRadar(canvas);let ctx=canvas.getContext('2d'),w=canvas.width,b=game.mapBounds();ctx.save();ctx.translate(w/2,w/2);ctx.scale(w/188,w/188);ctx.fillStyle='#071426dc';if(b.minX>-88)ctx.fillRect(-94,-94,b.minX+94,188);if(b.maxX<88)ctx.fillRect(b.maxX,-94,94-b.maxX,188);if(b.minZ>-88)ctx.fillRect(b.minX,-94,b.maxX-b.minX,b.minZ+94);if(b.maxZ<88)ctx.fillRect(b.minX,b.maxZ,b.maxX-b.minX,94-b.maxZ);ctx.strokeStyle='#ffc344';ctx.lineWidth=1;ctx.strokeRect(b.minX,b.minZ,b.maxX-b.minX,b.maxZ-b.minZ);ctx.fillStyle='#ffdf83';ctx.font='4px sans-serif';for(let a of PROGRESS.AREAS)if(a.stage>game.openMapStage())ctx.fillText('LOCK '+a.stage,a.x+(a.x<0?-20:4),a.z);ctx.restore();};
const progressStyle=document.createElement('style');progressStyle.textContent='.gate-tag{border:2px solid #ffc144;color:#ffe597}.material-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin:18px 0}.material-grid>div{padding:12px;border-radius:12px;background:#e4eee7;font-size:13px}.material-grid b{display:block;font-size:25px;color:#12794a}.material-grid .reserved{background:#17384c;color:white}.reserved b{color:#5bff9e}.work-orders{padding-left:22px;font-size:14px}.work-orders li{padding:7px 0;color:#59716c}.work-orders .current{color:#0b7857}.work-unlock{margin-top:15px;font-size:12px;color:#617672}.work-section h3{font-size:17px}#quest-peek small{display:block;margin-top:4px;color:#bce8de;font-size:11px}#material-shortcut{position:fixed;bottom:155px;left:16px;padding:9px 12px;background:#123e35;color:#83ffc0;border:1px solid #42e093;border-radius:9px;z-index:15;font-weight:700;font-size:12px}#material-shortcut[hidden]{display:none}';document.head.appendChild(progressStyle);
const progressHUD=updateExpansionHUD;updateExpansionHUD=function(){progressHUD();if(game.variant!=='tycoon')return;let el=$('supplies'),n=game.cityInventory('material');el.textContent=compactNumber(n);el.dataset.value=n;let stat=el.closest('.stat');stat.title='건설에 쓸 수 있는 재생 원료 · 눌러 수량 확인';stat.setAttribute('aria-label',stat.title);stat.onclick=()=>{if(game.variant==='tycoon')showMaterialStore();};};
const progressBuilding=showBaseBuilding;showBaseBuilding=function(id){progressBuilding(id);let d=OPS.BUILDINGS.find(d=>d.id===id);if(game.mapPositionOpen(d.x,d.z))return;let p=document.createElement('p');p.className='ops-benefit';p.textContent='🔒 승급 '+PROGRESS.required(d.x,d.z)+' 이후 이 구역으로 길이 열립니다.';$('modal').querySelector('h2').after(p);for(let id of ['ops-fund','city-fund'])if($(id)){$(id).disabled=true;$(id).textContent='구역 개방 후 건설';}};
const progressNetwork=showBaseNetwork;showBaseNetwork=function(){progressNetwork();for(let a of PROGRESS.AREAS){if(a.stage<=game.openMapStage())continue;let b=document.querySelector('[data-line="'+a.id+'"]');if(b){b.disabled=true;b.textContent='🔒 승급 '+a.stage+'에 구역 개방';}}};
progressStyle.textContent+='body:has(#overlay:not(.hidden)) .panel-hide,body:has(#overlay:not(.hidden)) #ops-notice,body:has(#overlay:not(.hidden)) #city-banner,body:has(#overlay:not(.hidden)) #toast{visibility:hidden!important}';

function takeLocalMaterial(source){if(game.variant!=='tycoon')return;let sale=source!=='store'&&Math.hypot(game.player.x+12,game.player.z-11)<=4;if(!sale&&Math.hypot(game.player.x-3.3,game.player.z-6)>6){game.waypoint={x:3.3,z:6};toast('초록 원료 발판으로 이동하세요');return;}let ok=sale?game.reclaimSaleMaterial(game.factory.lanes[0].stock):game.collectMaterial();if(ok){processEvents();save();updateExpansionHUD();}else toast('가져올 원료가 없어요');}

