function showManagement(){let m=game.management(),a=m.active,tier=Math.min(m.rank,commissionTier||m.rank),kind=a?CleanHouse.MANAGEMENT.TYPES.find(d=>d.id===a.id):null;let content='<button class="close" id="mg-close" aria-label="닫기">×</button><div class="eyebrow">CITY COMMISSIONS</div><h2>도시 도전 · 등급 '+m.rank+'</h2><p>도시 인장 '+m.seals+' · 성공 '+m.wins+' / 실패 '+m.losses+'</p><p>납품 → 운영비·습격 버티기 → 인장 연구 → 다음 등급. 3회 성공마다 등급이 올라갑니다.</p>';
if(a){content+='<section class="mg-active"><h3>'+kind.name+' · '+(a.phase==='boss'?'감독관 정화':'납품 진행')+'</h3><p>'+kind.desc+'</p><div id="mg-live"></div><button class="btn" id="mg-deliver">모은 물품 부분 납품</button><button class="btn secondary" id="mg-cool">긴급 냉각 −45 · 돈 120 + 원료 10</button><button class="btn ghost" id="mg-abandon">계약 포기 · 보증금 손실</button></section>';}else{content+='<label>도전 등급 <input id="mg-tier" type="number" min="1" max="'+m.rank+'" value="'+tier+'" style="width:80px;padding:10px"></label><p>해금한 이전 등급도 다시 도전할 수 있어요.</p><p role="status">'+((m.last||'도시 2단계부터 개방. 원하는 계약을 선택하세요.').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;'))+'</p><div class="mg-risk">'+[1,2,3].map(r=>'<button data-mg-risk="'+r+'" aria-pressed="'+(r===commissionRisk)+'">'+['일반','도전','극한'][r-1]+'</button>').join('')+'</div>'+CleanHouse.MANAGEMENT.TYPES.map(d=>{let o=game.commissionOffer(d.id,commissionRisk,tier),ok=game.commissionAvailable(d.id);return '<section class="enterprise-card"><h3>'+d.name+'</h3><p>'+d.desc+'</p><p>'+Object.entries(o.needs).map(([k,n])=>resourceName(k)+' '+n).join(' · ')+'</p><small>전체 물량의 25%는 계약 중 새로 생산 · 최소 75초 운영<br>제한 '+o.seconds+'초 · 운영비 '+game.commissionUpkeep(commissionRisk,tier)+'/30초<br>성공: 보증금 반환 + 돈 '+o.reward+' + 인장 '+o.seals+'<br>시작 보증금 '+o.bond+' · 현재 보유 돈 '+Math.floor(game.money)+'<br>실패/포기: 보증금·납품품·이미 낸 운영비 손실, 평판 −12</small><button class="btn" data-mg-start="'+d.id+'" '+(!ok||game.money<o.bond?'disabled':'')+'>'+(!ok?'도시 '+(d.stage+1)+'단계 + 해당 생산시설 필요':'보증금 '+o.bond+' 내고 시작')+'</button></section>';}).join('');}
content+='<h3>전문 연구 · 반복 투자</h3><p>인장은 계약 성공으로 획득합니다. 효과는 단계가 높아질수록 조금씩 증가해요.</p>'+Object.entries(CleanHouse.MANAGEMENT.TECH).map(([k,name])=>{let c=game.managementResearchCost(k),lv=m.tech[k];return '<section class="enterprise-card"><b>'+name+' Lv.'+lv+' · +'+Math.round(12*Math.log2(1+lv))+'% → +'+Math.round(12*Math.log2(2+lv))+'%</b><button class="btn secondary" data-mg-research="'+k+'" '+(m.seals<c.seals||!Object.entries(c).every(([k,n])=>k==='seals'||game.cityInventory(k)>=n)?'disabled':'')+'>'+Object.entries(c).map(([k,n])=>resourceName(k)+' '+n).join(' · ')+'</button></section>';}).join('')+'<button class="btn secondary" id="mg-support">정화센터 · 정비센터 · 배송본부 건설</button>';
showModal('management',content);if($('mg-tier'))$('mg-tier').onchange=()=>{commissionTier=Math.max(1,Math.min(m.rank,Math.floor(Number($('mg-tier').value)||1)));showManagement();};$('mg-close').onclick=closeModal;$('mg-support').onclick=showEnterprise;document.querySelectorAll('[data-mg-risk]').forEach(b=>b.onclick=()=>{commissionRisk=Number(b.dataset.mgRisk);showManagement();});document.querySelectorAll('[data-mg-start]').forEach(b=>b.onclick=()=>{if(game.startCommission(b.dataset.mgStart,commissionRisk,tier)){save();processEvents();closeModal();}});document.querySelectorAll('[data-mg-research]').forEach(b=>b.onclick=()=>{game.researchManagement(b.dataset.mgResearch);save();processEvents();showManagement();});if(a){$('mg-deliver').onclick=()=>{game.deliverCommission();save();processEvents();showManagement();};$('mg-cool').onclick=()=>{game.manageHeat();save();showManagement();};$('mg-abandon').onclick=()=>{showModal('mgcancel','<h2>보증금 '+a.bond+'을 포기할까요?</h2><p>납품한 물품과 운영비는 반환되지 않습니다.</p><button class="btn" id="mg-keep">계약 계속</button><button class="btn secondary" id="mg-cancel">포기 확정</button>');$('mg-keep').onclick=showManagement;$('mg-cancel').onclick=()=>{game.finishCommission(false,'계약 포기');save();processEvents();showManagement();};};updateManagementReadout();}}
function updateManagementReadout(){let m=game.management(),a=m.active;if(!a||!$('mg-live'))return;$('mg-live').innerHTML='<b>'+Math.ceil(a.left)+'초 · 다음 습격 '+Math.ceil(a.raid)+'초</b><p>과열 '+Math.round(m.heat)+'%'+(m.heat>=80?' · 생산 속도 −30%':' · 80%부터 생산 속도 −30%')+'</p><progress max="100" value="'+m.heat+'"></progress><p>운영비 '+game.commissionUpkeep()+' / '+Math.ceil(a.upkeep)+'초 뒤 · 누적 '+a.spent+'</p>'+Object.entries(a.needs).map(([k,n])=>'<p>'+resourceName(k)+' 납품 '+a.delivered[k]+'/'+n+' · 지금 가용 '+Math.floor(game.cityInventory(k))+' · 부족 '+Math.max(0,n-a.delivered[k]-Math.floor(game.cityInventory(k)))+' · 새 생산 '+Math.min(a.production[k],Math.ceil(n*.25))+'/'+Math.ceil(n*.25)+'</p>').join('')+'<p>최소 운영 '+Math.min(75,Math.floor(a.seconds-a.left))+'/75초 · 다음 진입 '+['북','동','남','서'][a.raidIndex%4]+'</p>';}
const mgMenu=showQuickMenu;showQuickMenu=function(){mgMenu();if(game.variant!=='tycoon')return;let b=document.createElement('button');b.className='btn';b.textContent='⚑ 도시 도전 · 반복 계약 / 연구';b.onclick=showManagement;$('menu-resume')?.before(b);};
const mgEvent=handleExpansionEvent;handleExpansionEvent=function(e){mgEvent(e);if(e.type==='commission_start')toast('계약 시작 · 납품과 새 생산, 75초 운영이 필요해요');if(e.type==='commission_raid'){toast(['북','동','남','서'][e.side]+'쪽 특수 습격! '+e.count+'마리');addPulse([0,30,0,-30][e.side],[ -30,0,30,0][e.side],0xff3355);}if(e.type==='commission_boss'){toast('북쪽 감독관 등장! 남은 시간 안에 정화하세요');addPulse(0,-29,0xff3355);}if(e.type==='commission_end'){toast((e.success?'도시 계약 성공!':'도시 계약 실패 · ')+e.reason);save();}if(e.type==='management_research')toast('전문 연구 Lv.'+e.level+' 적용');};
const mgStyle=document.createElement('style');mgStyle.textContent='.build-status{background:#172d43;color:#fff;padding:12px;border-radius:12px;margin:12px 0}.build-status span{display:block;font-size:14px;line-height:1.8}.build-status .missing{color:#ffb8b8}.build-status .enough{color:#84eab0}.build-receipt{background:#d5f8df;color:#17482b;padding:12px;border-radius:10px}.mg-risk{display:flex;gap:8px}.mg-risk button{padding:12px;border-radius:10px;border:2px solid #267b77;background:#fff}.mg-risk [aria-pressed=true]{background:#16485a;color:#fff}.mg-active{background:#172c43;color:#fff;padding:18px;border-radius:16px}.mg-active h3,.mg-active p{color:inherit}.mg-active progress{width:100%;height:14px;accent-color:#ff903b}';document.head.append(mgStyle);

const mgGerm=makeGerm;makeGerm=function(e){let g=mgGerm(e);if(e.commissionArmor){ring(g,0xffaa23,0,0,1.12,.13,.2);box(g,0xffaa23,0,1.75,0,.45,.45,.18);box(g,0x172c43,0,1.75,.12,.18,.28,.05);}if(e.commissionBoss)ring(g,0xff3d80,0,0,1.2,.14,.2);return g;};
mgStyle.textContent+='[data-procure]+small{display:block;margin:16px 0;line-height:1.6}.build-status+.build-receipt{margin:12px 0}';

const mgQuestClick=questPeek.onclick;questPeek.onclick=()=>{if(running&&game.variant==='tycoon'&&game.management().active)showManagement();else mgQuestClick();};
const mgRender=renderExpansion;let mgUiClock=0;renderExpansion=function(dt){mgRender(dt);if(game.variant!=='tycoon')return;mgUiClock+=dt;if(mgUiClock<.15)return;mgUiClock=0;let m=game.management(),a=m.active;questPeek.querySelector('.mg-live-peek')?.remove();if(a){let line=document.createElement('span');line.className='mg-live-peek';line.textContent='⚑ '+Math.ceil(a.left)+'초 · 과열 '+Math.round(m.heat)+'% · '+['북','동','남','서'][a.raidIndex%4]+'쪽 습격 '+Math.ceil(a.raid)+'초';questPeek.append(line);}};
mgStyle.textContent+='.mg-live-peek{display:block;color:#ffe286;font-size:11px;margin-top:6px;border-top:1px solid #ffffff40;padding-top:5px}';
