mgStyle.textContent+='#overlay{z-index:200}body:has(#overlay:not(.hidden)) #defense-shortcuts,body:has(#overlay:not(.hidden)) #toast{visibility:hidden!important}';

/* Optional rare encounter from an ambush chest. Menus disclose stakes before play. */
(function(){
 let rare=null;
 const distance=e=>Math.hypot(game.player.x-e.x,game.player.z-e.z);
 function current(){return rare&&game.enemies.find(e=>e.id===rare.id&&e.hp>0)||null;}
 function notice(html){$('modal').innerHTML=html;}
 function wrap(message,extra){
  closeModal();rare=null;game.player.hp=Math.max(1,game.player.hp-14);game.emit('damage',{x:game.player.x,z:game.player.z,n:14});
  let lost=0;if(game.carry>0){lost=Math.min(game.carry,Math.ceil(game.carry*.03));game.carry-=lost;}
  updateHUD();save();toast(message+(lost?' · 등짐 −'+lost:' · 기운 −14'));
 }
 function reward(enemy,coins,cores,label){
  if(enemy?.hp>0)game.hurt(enemy,enemy.hp+1);
  game.money+=coins;game.factory.cores+=cores;
  processEvents();
  closeModal();rare=null;updateHUD();save();toast(label+' · 도움 크레딧 +'+coins+' · 정화 결정 +'+cores);
 }
 function retreat(){closeModal();rare=null;}
 function duel(){
  const e=current();if(!e)return;
  let mine=0,theirs=0,round=0,last='';
  const hands=['가위','바위','보'],icons=['✌️','✊','✋'];
  function draw(){notice('<div class="chance-game"><small>수상한 세균 · 가위바위보</small><h2>이겨서 쫓아내세요</h2><p>무료 도전 · 먼저 2승이면 세균을 정화하고 크레딧과 결정을 얻어요.<br>패배하면 기운 −14, 등짐 최대 3%를 잃습니다.</p><div class="chance-score">나 '+mine+' <i>:</i> '+theirs+' 세균</div><div class="chance-last">'+last+'</div><div class="chance-hands">'+hands.map((h,i)=>'<button type="button" data-hand="'+i+'"><span>'+icons[i]+'</span>'+h+'</button>').join('')+'</div><button class="chance-back" id="chance-leave">물러나기</button></div>');$('chance-leave').onclick=retreat;$('modal').querySelectorAll('[data-hand]').forEach(b=>b.onclick=()=>play(+b.dataset.hand));}
  function play(pick){const enemy=Math.floor(game.rand()*3),d=(pick-enemy+3)%3;round++;let text='내 '+hands[pick]+' · 세균 '+hands[enemy]+' — ';if(!d){last=text+'비겼어요. 다시!';draw();return;}if(d===1){mine++;last=text+'승리!';}else{theirs++;last=text+'아쉬워요.';}if(mine>=2){reward(e,50+Math.floor(game.rand()*31),2,'승리! 세균을 설득했어요');return;}if(theirs>=2){wrap('세균이 이겼어요. 다음에는 이길 수 있어요.');return;}if(round>=5&&mine===theirs){wrap('비겼어요. 세균이 도망갔어요.');return;}draw();}
  draw();
 }
 function slot(){
  if(game.money<50){toast('슬롯 도전에는 도움 크레딧 50이 필요해요.');return;}
  const e=current();if(!e)return;game.money-=50;const roll=game.rand();
  if(roll<.025){reward(e,750,12,'잭팟! 황금 세균이 보물을 두고 갔어요');return;}
  if(roll<.25){reward(e,100,3,'대박! 세균이 보물을 두고 갔어요');return;}
  if(roll<.55){game.money+=25;game.player.hp=Math.min(100,game.player.hp+10);closeModal();rare=null;updateHUD();save();toast('아깝다! 크레딧 일부 회수 · 기운 +10');return;}
  let lost=0;if(game.carry>0&&game.rand()<.45){lost=Math.min(game.carry,Math.ceil(game.carry*.03));game.carry-=lost;}
  game.player.hp=Math.max(1,game.player.hp-14);game.emit('damage',{x:game.player.x,z:game.player.z,n:14});closeModal();rare=null;updateHUD();save();toast('꽝! 크레딧 −50'+(lost?' · 등짐 −'+lost:' · 기운 −14'));
 }
 function start(){const e=current();if(!e||distance(e)>6.5||game.variant!=='tycoon')return false;
  showModal('chance-encounter','<div class="chance-game"><small>희귀 조우 · 위험과 보상 공개</small><h2>세균이 승부를 걸었어요!</h2><p>보물상자 매복을 열었을 때 가끔 만나요.<br>가위바위보는 무료, 슬롯은 크레딧 50이에요.</p><div class="chance-choice"><button type="button" id="chance-duel"><span>✊</span><b>가위바위보</b><small>무료 · 이기면 +50~80 크레딧 · 결정 +2<br>지면 기운 −14 · 등짐 최대 3%</small></button><button type="button" id="chance-slot" '+(game.money<50?'disabled':'')+'><span>🎰</span><b>행운 슬롯 · 50</b><small>잭팟 2.5%: +750 · 결정 12<br>대박 22.5%: +100 · 결정 3<br>기운 보충 30%: 25 회수 · 기운 +10<br>꽝 45%: 비용 손실 · 등짐/기운 위험</small></button></div><button class="chance-back" id="chance-leave">승부하지 않고 계속</button></div>');$('chance-duel').onclick=duel;$('chance-slot').onclick=slot;$('chance-leave').onclick=retreat;return true;
 }
 const previous=handleExpansionEvent;
 handleExpansionEvent=function(e){previous(e);if(e.type!=='treasure'||game.variant!=='tycoon'||e.outcome!=='ambush'||game.rand()>.7)return;let target=game.enemies.filter(q=>q.kind==='runner'&&q.hp>0&&Math.hypot(q.x-e.x,q.z-e.z)<13).sort((a,b)=>Math.hypot(a.x-e.x,a.z-e.z)-Math.hypot(b.x-e.x,b.z-e.z))[0];if(!target)return;rare={id:target.id,until:game.totalTime+40};toast('매복 세균이 뜻밖의 승부를 걸었어요!');start();};
})();

buildEnvironment();updateHUD();showTitle();requestAnimationFrame(frame);
// Read-only state is useful for diagnostics; no hidden shortcuts alter a player's progress.
window.cleanHouseDiagnostics=()=>({chapter:game.chapter,mode:game.mode,wave:game.wave,time:game.time,paused:!running,modal:modalKind,baseHP:game.baseHP,money:game.money,carry:game.carry,player:{...game.player},enemies:game.enemies.length,towers:game.towers.length,drawCalls:renderer.info.render.calls,triangles:renderer.info.render.triangles,saveOk,supplies:game.supplies,helpCount:game.helpCount,totalCleaned:game.totalCleaned,dirt:game.dirt.length,combo:game.combo,comboMultiplier:game.comboMultiplier,fever:game.fever,puzzles:game.puzzles.map((s,i)=>({room:i,solved:s.solved,progress:game.puzzleProgress(i)})),nearPuzzle:game.puzzleNear()});

/* GamerClock adapter shares the game's lexical scope. */
/* GamerClock iframe adapter. Full progress stays in this browser; only scalar run results leave it. */
(function(){
 const bridge=window.GamerClockMiniGame;if(!bridge)return;
 const report=()=>({score:Math.min(5000000,Math.floor(game.totalCleaned||0)),durationMs:Math.floor((game.totalTime||0)*1000),result:game.dead?'lose':'complete',rankLabel:game.variant==='journey'?'Story · '+(game.chapter+1)+'/8':'City · '+(game.management().rank),stats:{mode:game.variant,cleaned:Math.floor(game.totalCleaned||0),wave:game.wave||0,storyChapter:game.chapter+1,contracts:game.variant==='tycoon'?game.management().wins:0}});
 const begin=beginMode;beginMode=function(mode){begin(mode);bridge.started({miniGameSlug:'clean-keep',mode});};
 const resume=continueGame;continueGame=function(){resume();if(saveSessionReady)bridge.started({miniGameSlug:'clean-keep',mode:game.variant,resumed:true});};
 const events=handleExpansionEvent;handleExpansionEvent=function(e){events(e);if(e.type==='journey_solved'||e.type==='commission_end'){bridge.scoreChanged({score:report().score});bridge.completed({...report(),result:e.type==='commission_end'?(e.success?'win':'lose'):'complete'});}};
 const menu=showQuickMenu;showQuickMenu=function(){menu();if(!saveSessionReady)return;let b=document.createElement('button');b.className='btn secondary';b.textContent=CleanHouse.language==='en'?'Send cleaning record to GamerClock':'GamerClock에 청소 기록 보내기';b.onclick=()=>{save();bridge.completed(report());toast(CleanHouse.language==='en'?'Record sent. Profile saving is below the game.':'기록을 보냈어요. 게임 아래에서 로그인 후 기록을 저장할 수 있어요.');};$('modal').append(b);};
 bridge.onContext(ctx=>{try{if(!localStorage.getItem('clean-keep-story-language')){CleanHouse.setStoryLanguage(String(ctx.locale||'ko').startsWith('ko')?'ko':'en');document.documentElement.lang=CleanHouse.language;if(modalKind==='title')showTitle();}}catch{}});
 bridge.ready({miniGameSlug:'clean-keep',version:'28.0.0'});
})();
